import { screens, modules, assets, componentCatalog, labTemplates, pipelineNodeTypes } from "./data.js";

export const escapeHtml = (value = "") => String(value).replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
export const getAsset = (state, id = state.selectedAsset) => state.assets.find(item => item.id === id) || state.assets[0];
export const getWorkspace = state => state.workspaces.find(item => item.id === state.activeWorkspace) || state.workspaces[0];
export const getLab = state => state.labs.find(item => item.id === state.selectedLab) || state.labs[0];
export const getPipeline = state => state.pipelines.find(item => item.id === state.selectedPipeline) || state.pipelines[0];
export const getNotebook = state => state.notebooks.find(item => item.id === state.selectedNotebook) || state.notebooks[0];
export const getRepository = state => state.repositories.find(item => item.id === state.selectedRepository) || state.repositories[0];
export const getProduct = state => state.products.find(item => item.id === state.selectedProduct) || state.products[0];
export const screenInfo = id => screens.find(item => item.id === id) || screens[0];

export function icon(name, size = 15) {
  const paths = {
    home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',
    workspace: '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h5M7 16h3"/>',
    discover: '<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5M8 11h5M10.5 8.5v5"/>',
    build: '<path d="M14 6 8 12l4 4 6-6M6 14l-3 3 4 4 3-3M13 4l3-3 7 7-3 3"/>',
    products: '<path d="m12 3 8 4.5v9L12 21l-8-4.5v-9z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>',
    operate: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.5 2"/>',
    deliver: '<path d="M4 19V5l8 4 8-4v14l-8-4z"/><path d="M12 9v6"/>',
    govern: '<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11z"/><path d="m9 12 2 2 4-4"/>',
    settings: '<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.7 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.7-1l-1.7.6-1.4-2.4 1.4-1.1a7 7 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.6a8 8 0 0 1 1.7-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.7 1l1.7-.6 1.4 2.4-1.4 1.1a7 7 0 0 1 0 2z" transform="translate(-1 -1)"/>',
    table: '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M9 9v11M15 9v11"/>',
    code: '<path d="m8 7-5 5 5 5M16 7l5 5-5 5M14 4l-4 16"/>',
    notebook: '<path d="M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2zM8 3v18M3 8h5M3 14h5"/>',
    pipeline: '<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><rect x="10" y="3" width="6" height="6" rx="1"/><rect x="8" y="15" width="7" height="6" rx="1"/><path d="M7 6h3M13 9v3h5v4M13 12l-2 3"/>',
    lab: '<path d="M9 3h6M10 3v7l-5.5 9a2 2 0 0 0 1.7 3h11.6a2 2 0 0 0 1.7-3L14 10V3M8 15h8"/>',
    search: '<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',
    git: '<path d="M6 3v12M18 9v12M6 9a3 3 0 1 0 0 6M18 3a3 3 0 1 0 0 6M6 9c0-3 3-3 6-3s3-3 6-3"/>',
    spark: '<path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-2-5.8L4 11l6-2.2zM19 14l1.1 2.9L23 18l-2.9 1.1L19 22l-1.1-2.9L15 18l2.9-1.1z"/>',
    close: '<path d="m6 6 12 12M18 6 6 18"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>',
    play: '<path d="m8 5 12 7-12 7z"/>',
    database: '<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',
    file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h8"/>',
    graph: '<circle cx="6" cy="6" r="2"/><circle cx="18" cy="6" r="2"/><circle cx="12" cy="18" r="2"/><path d="M8 7l3 8M16 7l-3 8M8 6h8"/>',
    bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
    refresh: '<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.6 9a7 7 0 0 1 11.8-2L20 12M4 12l2.6 5a7 7 0 0 0 11.8-2"/>',
    filter: '<path d="M4 5h16M7 12h10M10 19h4"/>',
    more: '<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'
  };
  return `<svg class="nav-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.file}</svg>`;
}

export const badge = (label, tone = "") => `<span class="badge ${tone}"><i class="badge-dot"></i>${escapeHtml(label)}</span>`;
export const button = (label, action, tone = "secondary", extra = "") => `<button class="button ${tone}" type="button" data-action="${action}" ${extra}>${label}</button>`;
export const screenButton = (label, screen, tone = "secondary", extra = "") => `<button class="button ${tone}" type="button" data-screen="${screen}" ${extra}>${label}</button>`;
const card = (title, body, opts = {}) => `<section class="panel-card ${opts.className || ""}">${title ? `<div class="panel-card-head"><h2>${title}</h2>${opts.action || ""}</div>` : ""}<div class="panel-card-body">${body}</div></section>`;
const pageHead = (title, description, actions = "", eyebrow = "DEXTER WORKSPACE") => `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`;
const stat = (label, value, foot, iconName = "table", tone = "") => `<div class="stat-card"><span class="stat-label">${icon(iconName, 12)} ${label}</span><strong class="stat-value ${tone}">${value}</strong><span class="stat-foot">${foot}</span></div>`;
const field = (label, name, value, type = "text", hint = "") => `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escapeHtml(value)}" data-model="${name}">${hint ? `<small>${hint}</small>` : ""}</div>`;
const selectField = (label, name, value, options, extra = "") => `<div class="field"><label for="${name}">${label}</label><select id="${name}" data-model="${name}" ${extra}>${options.map(option => `<option ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}</select></div>`;
const table = (headers, rows, opts = {}) => `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.length ? rows.join("") : `<tr><td colspan="${headers.length}"><div class="empty-state"><strong>No matching items</strong><p>Change the filter or create an item to continue.</p></div></td></tr>`}</tbody></table></div>`;
const assetRow = (asset, action = "open-asset") => `<tr class="selectable" data-action="${action}" data-id="${asset.id}"><td><span class="row-icon ${asset.environment === "LOCAL" ? "green" : ""}">${asset.type === "Table" ? "▦" : asset.type === "Kafka topic" ? "◉" : "◇"}</span> <span class="mono">${escapeHtml(asset.fullName)}</span></td><td>${badge(asset.environment, asset.environment === "LOCAL" ? "green" : asset.environment === "PROD" ? "amber" : "blue")}</td><td>${escapeHtml(asset.type)}</td><td>${escapeHtml(asset.owner)}</td><td>${badge(asset.classification, asset.classification === "Restricted" ? "red" : asset.classification === "Synthetic" ? "purple" : "")}</td><td>${escapeHtml(asset.updated)}</td><td>${asset.local ? badge("Local copy", "green") : asset.exportAllowed === false ? `<span class="access-blocked">⛨ Restricted</span>` : "—"}</td></tr>`;
const operationRow = (op, withActions = true) => `<div class="compact-row"><span class="row-icon ${op.state === "Failed" ? "" : op.state === "Completed" ? "green" : "amber"}">${op.type === "Materialization" ? "↓" : op.type === "Pipeline run" ? "⌁" : "◷"}</span><div class="row-main"><strong>${escapeHtml(op.target)}</strong><small>${escapeHtml(op.type)} · ${escapeHtml(op.phase || op.state)} ${op.rows ? `· ${escapeHtml(op.rows)}` : ""}</small>${op.progress < 100 ? `<div class="progress-track ${op.state === "Failed" ? "error" : ""}" style="margin-top:6px"><span style="width:${op.progress}%"></span></div>` : ""}</div>${badge(`${op.progress}% · ${op.state}`, op.state === "Failed" ? "red" : op.state === "Completed" ? "green" : "amber")}${withActions ? `<button class="icon-button" data-action="open-operation" data-id="${op.id}" aria-label="Open ${escapeHtml(op.target)}">›</button>` : ""}</div>`;
const assetOptions = (state, filter = () => true) => state.assets.filter(filter).map(asset => `<option value="${asset.id}">${escapeHtml(asset.fullName)}</option>`).join("");

function renderHome(state) {
  const active = state.operations.filter(op => ["Queued", "Starting", "Reading Metadata", "Extracting", "Transferring", "Registering", "Running", "Validating"].includes(op.state));
  const failed = state.operations.filter(op => op.state === "Failed").slice(0, 2);
  const latest = state.workspaces.slice(0, 3);
  return `<div class="page"><section class="hero-strip"><div><span class="eyebrow">TUESDAY · NOVEMBER 03, 2026</span><h1>Good morning, Henrique</h1><p>Pick up your engineering work or explore the data landscape.</p></div><div class="hero-numbers"><div class="hero-number"><strong>${state.workspaces.length}</strong><small>workspaces</small></div><div class="hero-number"><strong>${state.assets.length}</strong><small>discoverable assets</small></div><div class="hero-number"><strong>${state.labs.filter(l => l.status === "Running").length}</strong><small>active Labs</small></div><div class="hero-number"><strong>${state.prs.length}</strong><small>open reviews</small></div></div></section>
    <div class="toolbar" style="margin-top:11px">${screenButton(`${icon("plus",12)} New Workspace`, "workspaces", "primary", 'data-action="new-workspace"')}${screenButton(`${icon("lab",12)} Create Lab`, "lab-gallery")}${screenButton(`${icon("search",12)} Explore Data`, "discover")}${button(`${icon("notebook",12)} New Notebook`, "create-quick", "secondary", 'data-kind="notebook"')}${button(`${icon("pipeline",12)} New Pipeline`, "create-quick", "secondary", 'data-kind="pipeline"')}${button(`${icon("products",12)} New Data Product`, "create-product", "secondary")}</div>
    <div class="home-grid"><div>${card(`Active operations <span class="badge amber">${active.length} in progress</span>`, `<div class="compact-list">${active.map(op => operationRow(op)).join("") || `<div class="empty-state compact"><strong>All clear</strong><p>No active operations right now.</p></div>`}</div>`, { action: screenButton("View all", "operations", "ghost") })}${failed.length ? card(`Needs attention <span class="badge red">${failed.length} failed</span>`, `<div class="compact-list">${failed.map(op => operationRow(op)).join("")}</div>`, { action: screenButton("Review failures", "execution-console", "ghost") }) : ""}${card(`Recent workspaces`, `<div class="compact-list">${latest.map(ws => `<div class="compact-row"><span class="row-icon amber">⌂</span><div class="row-main"><strong>${escapeHtml(ws.name)}</strong><small>${escapeHtml(ws.domain)} · ${escapeHtml(ws.updated)} · ${escapeHtml(ws.testReadiness)}</small></div><button class="button ghost" data-action="open-workspace" data-id="${ws.id}">Open</button></div>`).join("")}</div>`, { className: "wide", action: screenButton("All workspaces", "workspaces", "ghost") })}</div><div>${card("Local runtime", `<div class="settings-row"><div><strong>DuckDB Local</strong><small>Query engine · ready</small></div>${badge("Ready", "green")}</div><div class="settings-row"><div><strong>Python Local</strong><small>Notebook runtime</small></div>${badge("Ready", "green")}</div><div class="settings-row"><div><strong>PySpark Local</strong><small>Lab runtime</small></div>${badge("Mock", "blue")}</div><div class="settings-row"><div><strong>Databricks</strong><small>Connections are simulated</small></div>${badge("Demo", "amber")}</div>`, { action: screenButton("Settings", "settings", "ghost") })}${card("Pending review", `<div class="compact-row"><span class="row-icon">⑂</span><div class="row-main"><strong>${escapeHtml(state.prs[0]?.title || "No open reviews")}</strong><small>${escapeHtml(state.prs[0]?.repository || "")} · ${escapeHtml(state.prs[0]?.state || "")}</small></div></div><div class="compact-row"><span class="row-icon green">✓</span><div class="row-main"><strong>Streaming risk late-event window</strong><small>All tests passing · Ready for review</small></div></div>`, { action: screenButton("Delivery", "delivery-status", "ghost") })}</div><section class="wide">${card("Shared data landscape", `<div class="table-wrap"><table class="data-table"><thead><tr><th>Asset</th><th>Environment</th><th>Type</th><th>Owner</th><th>Classification</th><th>Freshness</th><th>Local</th></tr></thead><tbody>${state.assets.slice(0, 5).map(asset => assetRow(asset)).join("")}</tbody></table></div>`, { action: screenButton("Explore catalog", "discover", "ghost") })}</section></div></div>`;
}

function renderWorkspaces(state) {
  const query=state.workspaceSearch.toLowerCase();
  const list = state.workspaces.filter(ws => (!query || `${ws.name} ${ws.domain} ${ws.description}`.toLowerCase().includes(query)) && (state.workspaceFilter !== "favorites" || state.favorites.includes(ws.id)));
  return `<div class="page">${pageHead("Workspaces", "Project areas connect data assets, Labs, pipelines, notebooks and delivery configuration.", button(`${icon("plus",12)} New workspace`, "new-workspace", "primary"), "PROJECTS / WORKSPACES")}<div class="screen-filter"><input class="search-input" placeholder="Filter workspaces…" data-filter="workspaces" value="${escapeHtml(state.workspaceSearch)}"><div class="segmented"><button class="segment ${state.workspaceFilter==="all"?"active":""}" data-action="filter-all">All projects</button><button class="segment ${state.workspaceFilter==="favorites"?"active":""}" data-action="filter-favorites">Favorites</button></div><span class="badge">${list.length} workspaces</span></div><div class="card-grid" style="margin-top:11px">${list.map(ws => `<article class="workspace-card"><div class="toolbar">${badge(ws.domain, "blue")}${ws.id === state.activeWorkspace ? badge("Current", "amber") : ""}<button class="icon-button" data-action="favorite-workspace" data-id="${ws.id}" aria-label="Favorite ${escapeHtml(ws.name)}">${state.favorites.includes(ws.id) ? "★" : "☆"}</button></div><h3>${escapeHtml(ws.name)}</h3><p>${escapeHtml(ws.description)}</p><div class="workspace-meta"><span>⌂ ${escapeHtml((ws.labId||"Unassigned").replace("lab-", ""))} Lab</span><span>▦ ${ws.assets.length} assets</span><span>⌁ ${ws.pipelineIds.length} pipeline</span><span>⑂ ${escapeHtml(ws.testReadiness)}</span></div><div class="card-foot"><span class="tiny mono">${escapeHtml(ws.repository)}</span><button class="button secondary" data-action="open-workspace" data-id="${ws.id}">Open workspace →</button></div></article>`).join("") || `<div class="empty-state"><strong>No workspaces match</strong><p>Change the search or favorite filter.</p></div>`}</div></div>`;
}

function renderWorkspaceOverview(state) {
  const ws = getWorkspace(state);
  const wsAssets = state.assets.filter(a => ws.assets.includes(a.id));
  return `<div class="page">${pageHead(ws.name, ws.description, `${button("Workspace settings", "workspace-settings")}${button(`${icon("plus",12)} Add asset`, "attach-asset", "primary")}`, "WORKSPACE / OVERVIEW")}<div class="card-grid four">${stat("Linked assets", wsAssets.length, "Tables, topics and local datasets", "table")}${stat("Development Labs", 1, `${getLab(state).status} · ${getLab(state).template}`, "lab")}${stat("Pipelines", ws.pipelineIds.length, "1 failed run needs attention", "pipeline")}${stat("Delivery readiness", state.testReadiness ? "Ready" : "Review", state.testReadiness ? "Tests passing" : "1 schema check failing", "deliver", state.testReadiness ? "" : "")}</div><div class="split-layout" style="margin-top:11px"><div>${card("Related data assets", table(["Asset", "Environment", "Type", "Owner", "Classification", "Freshness", "Local"], wsAssets.map(a => assetRow(a))))}${card("Development Lab", `<div class="compact-row"><span class="row-icon amber">⌂</span><div class="row-main"><strong>${escapeHtml(getLab(state).name)}</strong><small>${escapeHtml(getLab(state).template)} · ${getLab(state).components.length} services</small></div>${badge(getLab(state).status, getLab(state).status === "Running" ? "green" : "")}${screenButton("Open cockpit", "lab-cockpit")}</div>`, { action: screenButton("Configure", "lab-composer", "ghost") })}</div><div>${card("Repository", `<div class="settings-row"><div><strong>${escapeHtml(ws.repository)}</strong><small>${escapeHtml(ws.branch)}</small></div>${badge("Connected · simulated", "blue")}</div><div class="settings-row"><div><strong>Default target</strong><small>${escapeHtml(state.adapter)}</small></div>${screenButton("Configure", "artifact-preview", "ghost")}</div>`, { action: screenButton("Browse repository", "repositories", "ghost") })}${card("Build resources", `<div class="compact-row"><span class="row-icon">⌁</span><div class="row-main"><strong>${escapeHtml(ws.pipelineIds[0] || "No pipelines")}</strong><small>Pipeline · ${state.pipelines[0].nodes.length} steps</small></div>${screenButton("Open", "pipeline-studio", "ghost")}</div><div class="compact-row"><span class="row-icon">▤</span><div class="row-main"><strong>${escapeHtml(ws.notebookIds[0] || "No notebooks")}</strong><small>Notebook · Python Local</small></div>${screenButton("Open", "notebook-studio", "ghost")}</div>`, { action: button("Create pipeline", "create-quick", "ghost", 'data-kind="pipeline"') })}${card("Recent validation", `<div class="compact-row"><span class="row-icon">✓</span><div class="row-main"><strong>${escapeHtml(ws.testReadiness)}</strong><small>Customer profile contract · 1 compatibility warning</small></div></div><div class="compact-row"><span class="row-icon">◷</span><div class="row-main"><strong>Pipeline run · 18 min ago</strong><small>Failed at contract validation</small></div></div>`, { action: screenButton("Test center", "test-center", "ghost") })}</div></div></div>`;
}

function renderDiscover(state) {
  const query=state.discoverSearch.toLowerCase();
  const list = state.assets.filter(asset => (!query || `${asset.fullName} ${asset.owner} ${asset.type}`.toLowerCase().includes(query)) && (state.discoverEnvironment==="All"||asset.environment===state.discoverEnvironment) && (state.discoverDomain==="All"||asset.domain===state.discoverDomain));
  return `<div class="page">${pageHead("Data Explorer", "Browse assets across LOCAL, DEV and PROD. Permissions and local export policy are visible on each asset.", `${button("Compare selected", "compare-assets")}${button("Refresh catalog", "refresh-catalog")}`, "DISCOVER / CATALOG")}<div class="screen-filter"><input class="search-input" data-filter="assets" placeholder="Search tables, topics, APIs…" value="${escapeHtml(state.discoverSearch)}"><select class="search-input" data-filter-environment><option value="All" ${state.discoverEnvironment==="All"?"selected":""}>All environments</option>${["LOCAL", "DEV", "PROD"].map(env => `<option ${state.discoverEnvironment===env?"selected":""}>${env}</option>`).join("")}</select><select class="search-input" data-filter-domain><option value="All" ${state.discoverDomain==="All"?"selected":""}>All domains</option>${["Customer", "Sales", "Finance", "Risk"].map(domain => `<option ${state.discoverDomain===domain?"selected":""}>${domain}</option>`).join("")}</select>${badge("Catalog synced 3 min ago", "green")}</div><div class="split-layout" style="margin-top:10px;grid-template-columns:minmax(0,1fr) 225px"><div>${table(["Asset", "Environment", "Type", "Owner", "Classification", "Freshness", "Local"], list.map(asset => assetRow(asset)))}</div><div>${card("Environment scope", `<div class="tree-card"><div class="tree-card-title">▣ PROD <span class="tiny">· 2 catalogs</span></div><div class="tree-card-children"><div class="tree-card-child">sales <span class="tiny">· 18 schemas</span></div><div class="tree-card-child">finance <span class="tiny">· restricted</span></div></div></div><div class="tree-card" style="margin-top:7px"><div class="tree-card-title">◇ DEV <span class="tiny">· 3 catalogs</span></div><div class="tree-card-children"><div class="tree-card-child">customer</div><div class="tree-card-child">risk</div></div></div><div class="tree-card" style="margin-top:7px"><div class="tree-card-title">◉ LOCAL <span class="tiny">· ${state.assets.filter(a => a.environment === "LOCAL").length} datasets</span></div><div class="tree-card-children"><div class="tree-card-child">Workspace storage</div><div class="tree-card-child">Synthetic datasets</div></div></div>`, { action: screenButton("Manage local data", "local-data", "ghost") })}${card("Selected asset", `<strong class="mono">${escapeHtml(getAsset(state).fullName)}</strong><p class="tiny">${escapeHtml(getAsset(state).description)}</p><div class="toolbar">${screenButton("Open workbench", "table-workbench", "secondary", `data-id="${getAsset(state).id}"`)}${button("Ask Dexter", "attach-current-context", "ghost")}</div>`)}</div></div></div>`;
}

function renderTableWorkbench(state) {
  const asset = getAsset(state); const tab = state.assetTab || "Overview";
  let body = "";
  if (tab === "Schema") body = table(["Column", "Type", "Nullability", "Key / policy"], asset.schema.map(([name, type, nullable, note]) => `<tr><td class="mono">${escapeHtml(name)}</td><td class="mono">${escapeHtml(type)}</td><td>${escapeHtml(nullable)}</td><td>${escapeHtml(note || "—")}</td></tr>`));
  else if (tab === "Data Preview") body = table(asset.schema.map(field => field[0]), asset.samples.map(row => `<tr>${row.map(value => `<td>${escapeHtml(value)}</td>`).join("")}</tr>`));
  else if (tab === "Lineage") body = `<div class="lab-topology">${["${asset.environment} source", asset.fullName, "customer_incremental_ingest", "Customer 360"].map((title, i) => `<button class="service-node" data-action="lineage-node" data-index="${i}"><strong>${escapeHtml(title.replace("${asset.environment}", asset.environment))}</strong><small>${i === 0 ? "Upstream" : i === 3 ? "Downstream product" : "Related asset"}</small></button>`).join("")}</div>`;
  else if (tab === "Profile") body = `<div class="card-grid three">${stat("Rows", asset.rows.toLocaleString(), "Latest observed", "table")}${stat("Null customer_tier", "1.8%", "Within 2% threshold", "filter")}${stat("Distinct customers", "182.4K", "Cardinality 0.99", "graph")}</div><div class="chart-bars">${[28,48,37,68,52,82,64,93,58,75,46,61].map((height, i) => `<div class="chart-bar" style="height:${height}%"><span>${["Mon","Tue","Wed","Thu","Fri","Sat","Sun","Mon","Tue","Wed","Thu","Fri"][i]}</span></div>`).join("")}</div>`;
  else if (tab === "Quality") body = table(["Rule", "Result", "Threshold", "Evidence"], [`<tr><td>Primary key uniqueness</td><td>${badge("Passed", "green")}</td><td>100%</td><td>0 duplicates</td></tr>`, `<tr><td>customer_tier null rate</td><td>${badge("Warning", "amber")}</td><td>&lt; 2%</td><td>1.8%</td></tr>`, `<tr><td>Freshness</td><td>${badge("Passed", "green")}</td><td>&lt; 24 hours</td><td>3 min</td></tr>`]);
  else if (tab === "History") body = `<div class="timeline"><div class="timeline-item done"><strong>Schema v3 · customer_tier added</strong><small>Oct 28 · Henrique Silva · 6 fields</small></div><div class="timeline-item done"><strong>Schema v2 · consent preference normalized</strong><small>Oct 14 · Customer Data Office</small></div><div class="timeline-item"><strong>Materialized to LOCAL</strong><small>Today, 09:18 · ${escapeHtml(asset.rows.toLocaleString())} rows</small></div></div>`;
  else if (tab === "Permissions") body = table(["Principal", "Permission", "Scope", "Local export"], [`<tr><td>Customer Data</td><td>Owner</td><td>${asset.environment}</td><td>${badge("Allowed", "green")}</td></tr>`, `<tr><td>Data Engineering</td><td>SELECT</td><td>${asset.environment}</td><td>${asset.exportAllowed === false ? badge("Blocked", "red") : badge("Allowed", "green")}</td></tr>`]);
  else body = `<div class="card-grid three">${stat("Record count", Number(asset.rows).toLocaleString(), "Last analyzed 3 min ago", "table")}${stat("Storage size", asset.size, `${asset.environment} source`, "database")}${stat("Freshness", asset.updated, `Owner · ${escapeHtml(asset.owner)}`, "operate")}</div><div class="split-layout" style="margin-top:10px">${card("About this asset", `<p class="tiny">${escapeHtml(asset.description)}</p><div class="settings-row"><div><strong>Data classification</strong><small>Governed metadata</small></div>${badge(asset.classification, asset.classification === "Restricted" ? "red" : "")}</div><div class="settings-row"><div><strong>Local availability</strong><small>${asset.local ? `Last materialized ${escapeHtml(asset.localUpdated)}` : "No local snapshot"}</small></div>${asset.local ? badge(asset.localStatus, "green") : badge("Remote only")}</div>`, { action: button("View contract", "navigate-contracts", "ghost") })}${card("Sample records", table(asset.schema.map(field => field[0]), asset.samples.slice(0, 3).map(row => `<tr>${row.map(value => `<td>${escapeHtml(value)}</td>`).join("")}</tr>`)), { action: `<button class="button ghost" data-action="asset-tab" data-tab="Data Preview">Full preview →</button>` })}</div>`;
  const tabs = ["Overview", "Schema", "Data Preview", "Profile", "Quality", "Lineage", "History", "Permissions"];
  return `<div class="page"><div class="asset-header"><div class="asset-title"><span class="row-icon amber">▦</span><div><span class="eyebrow">${escapeHtml(asset.environment)} / ${escapeHtml(asset.type.toUpperCase())}</span><h1>${escapeHtml(asset.fullName)}</h1><p>${escapeHtml(asset.description)}</p></div></div><div class="page-actions">${button("Compare", "navigate-compare")}${button("Materialize to Local", "start-movement", asset.exportAllowed === false ? "danger" : "primary")}</div></div><div class="toolbar" style="margin-bottom:10px">${button("Open in SQL", "open-sql")}${button("Open in Notebook", "open-notebook")}${button("Generate Synthetic", "open-synthetic")}${button("Add to Pipeline", "add-to-pipeline")}${button("Add to Product", "add-to-product")}${button("View Contract", "navigate-contracts")}</div><div class="asset-tabs">${tabs.map(item => `<button class="asset-tab ${tab === item ? "active" : ""}" data-action="asset-tab" data-tab="${item}">${item}</button>`).join("")}</div><div style="padding-top:10px">${body}</div></div>`;
}

function renderCompare(state) {
  const left = state.assets.find(a => a.id === state.compareAssets[0]) || state.assets[0]; const right = state.assets.find(a => a.id === state.compareAssets[1]) || state.assets[1];
  const names = new Set([...left.schema.map(x => x[0]), ...right.schema.map(x => x[0])]);
  const rows = [...names].map(name => { const l = left.schema.find(x => x[0] === name), r = right.schema.find(x => x[0] === name); const changed = !l || !r || l[1] !== r[1] || l[2] !== r[2]; return `<tr><td>${!l ? badge("Added", "green") : !r ? badge("Removed", "red") : changed ? badge("Changed", "amber") : badge("Same", "green")}</td><td class="mono">${escapeHtml(name)}</td><td>${l ? escapeHtml(l[1]) : "—"}</td><td>${r ? escapeHtml(r[1]) : "—"}</td><td>${l ? escapeHtml(l[2]) : "—"}</td><td>${r ? escapeHtml(r[2]) : "—"}</td></tr>`; });
  return `<div class="page">${pageHead("Compare tables", "Review schema, nullability, volume and sample records across environments.", button("Compatibility recommendation", "compare-recommendation"), "DISCOVER / COMPARE")}<div class="form-grid two-layout"><div class="field"><label>Left asset</label><select data-model="compare-left">${assetOptions(state).replace(`value="${left.id}"`, `value="${left.id}" selected`)}</select></div><div class="field"><label>Right asset</label><select data-model="compare-right">${assetOptions(state).replace(`value="${right.id}"`, `value="${right.id}" selected`)}</select></div></div><div class="card-grid four" style="margin-top:10px">${stat("Schema changes", rows.filter(row => /Changed|Added|Removed/.test(row)).length, "Column-level comparison", "table")}${stat("Left rows", Number(left.rows).toLocaleString(), left.environment, "database")}${stat("Right rows", Number(right.rows).toLocaleString(), right.environment, "database")}${stat("Compatibility", "Review", "Schema differs in 2 columns", "govern")}</div>${card(`Structural diff · ${escapeHtml(left.environment)} ↔ ${escapeHtml(right.environment)}`, table(["Change", "Column", `${escapeHtml(left.environment)} type`, `${escapeHtml(right.environment)} type`, "Nullability · left", "Nullability · right"], rows))}<div class="diff-view" style="margin-top:10px"><div class="diff-pane"><div class="diff-head">${escapeHtml(left.fullName)} · sample</div>${left.samples.map(r => `<div class="diff-line"><span class="line-no">${escapeHtml(r[0])}</span>${escapeHtml(r.slice(1).join(" · "))}</div>`).join("")}</div><div class="diff-pane"><div class="diff-head">${escapeHtml(right.fullName)} · sample</div>${right.samples.map(r => `<div class="diff-line ${left.samples[0]?.[1] !== r[1] ? "added" : ""}"><span class="line-no">${escapeHtml(r[0])}</span>${escapeHtml(r.slice(1).join(" · "))}</div>`).join("")}</div></div></div>`;
}

function renderSynthetic(state) {
  const cfg = state.syntheticConfig; const source = state.assets.find(a => a.id === cfg.source) || state.assets[0];
  return `<div class="page">${pageHead("Synthetic Data Studio", "Create structurally realistic test data without copying sensitive source records.", `${button("Validate configuration", "validate-synthetic")}${button("Generate dataset", "generate-synthetic", "primary")}`, "DISCOVER / SYNTHETIC DATA")}<div class="split-layout"><div class="form-stack">${card("Dataset configuration", `<div class="form-grid">${selectField("Schema source", "synthetic-source", cfg.source, state.assets.map(a => a.id))}${selectField("Destination", "synthetic-destination", cfg.destination, ["Local workspace", "Customer Ingestion Lab", "Project storage"])}${field("Rows to generate", "synthetic-rows", cfg.rows, "number", "The demo will register a simulated dataset.")}${selectField("Primary key behavior", "synthetic-key", "Unique and sequential", ["Unique and sequential", "Deterministic hash", "Allow duplicates"])}${selectField("Distribution profile", "synthetic-distribution", "Match source profile", ["Match source profile", "Uniform", "Right skewed", "Long tail"])}${selectField("Temporal pattern", "synthetic-temporal", "Business-day activity", ["Business-day activity", "Uniform over time", "Month-end peak"])}</div><div class="section-heading"><h2>Constraints & edge cases</h2></div><div class="pill-row">${["Preserve PK/FK relationships", "Null edge cases", "Boundary values", "Duplicate scenario", "Schema evolution", "PII-safe values"].map(label => `<label class="pill-select"><input type="checkbox" data-synthetic-option="${escapeHtml(label)}" ${(state.syntheticOptions||[]).includes(label)?"checked":""}>${label}</label>`).join("")}</div>`, { action: badge("PII-safe generation", "green") })}${card("Validation", `<div class="notice success"><span>✓</span><div><strong>Schema is ready</strong> ${source.schema.length} columns · ${source.schema.filter(x => x[3].includes("PK")).length || 1} key field · referential constraints preserved.</div></div><div class="settings-row"><div><strong>Preview records</strong><small>Deterministic demo rows</small></div>${button("Refresh preview", "refresh-synthetic-preview", "ghost")}</div><div class="table-wrap"><table class="data-table"><thead><tr>${source.schema.slice(0,4).map(x=>`<th>${escapeHtml(x[0])}</th>`).join("")}</tr></thead><tbody>${source.samples.slice(0,2).map(row=>`<tr>${row.slice(0,4).map(x=>`<td>${escapeHtml(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`)}</div><div>${card("Generation preview", `<div class="metric-row">${[ ["Rows", Number(cfg.rows).toLocaleString()], ["Estimated size", `${Math.max(2, Math.round(Number(cfg.rows) * .00024))} MB`], ["Columns", source.schema.length] ].map(([label,value])=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`).join("")}</div><div class="section-heading"><h2>Configured behavior</h2></div><div class="settings-row"><div><strong>Null ratio</strong><small>Nullable fields only</small></div><span class="mono">2.0%</span></div><div class="settings-row"><div><strong>Cardinality</strong><small>customer_id · unique</small></div><span class="mono">100%</span></div><div class="settings-row"><div><strong>Temporal spread</strong><small>Created at</small></div><span class="mono">90 days</span></div><div class="settings-row"><div><strong>Relationships</strong><small>Foreign keys retained</small></div>${badge("Valid", "green")}</div>`, { action: badge("Ready", "green") })}${card("Registered datasets", `<div class="compact-list">${state.assets.filter(a=>a.classification === "Synthetic").map(a=>`<div class="compact-row"><span class="row-icon">▦</span><div class="row-main"><strong>${escapeHtml(a.fullName)}</strong><small>${Number(a.rows).toLocaleString()} rows · ${escapeHtml(a.size)}</small></div>${screenButton("Open", "table-workbench", "ghost", `data-id="${a.id}"`)}</div>`).join("") || `<p class="tiny">Generated datasets appear here and in Discover.</p>`}</div>`)}</div></div></div>`;
}

function renderLocalData(state) {
  const local=state.assets.filter(asset=>asset.environment==="LOCAL");const selected=local.find(asset=>asset.id===state.selectedLocalAsset)||local[0];
  const stored=local.reduce((sum,asset)=>sum+(Number.parseFloat(asset.size)||0),0);
  return `<div class="page">${pageHead("Local Data", "Datasets materialized to this workspace for local SQL, notebook and pipeline development.", `${button("New materialization", "start-movement", "primary")}${button("Storage details", "storage-details")}`, "DISCOVER / LOCAL DATA")}<div class="card-grid four">${stat("Local datasets", local.length, "Current snapshots", "database")}${stat("Storage used", `${stored.toFixed(1)} MB`, "Local demo catalog estimate", "file")}${stat("Previous snapshots", `${local.filter(asset=>asset.sourceAssetId).length} retained`, "Maximum 1 per table · 24h TTL", "refresh")}${stat("Processing engines", "3", "DuckDB · Python · PySpark", "build")}</div>${card("Materialized datasets", table(["Dataset", "Source", "Rows", "Format", "Size", "Updated", "Status", "Actions"], local.map(asset=>{const source=asset.sourceAssetId?state.assets.find(item=>item.id===asset.sourceAssetId):null;return `<tr><td class="mono">${escapeHtml(asset.fullName)}</td><td>${escapeHtml(source?.fullName||"Synthetic Lab")}</td><td class="numeric">${Number(asset.rows).toLocaleString()}</td><td>${escapeHtml(asset.format||"Parquet")}</td><td>${escapeHtml(asset.size)}</td><td>${escapeHtml(asset.localUpdated||asset.updated)}</td><td>${badge(asset.localStatus||"Ready","green")}</td><td><div class="toolbar">${button("Preview","preview-local","ghost",`data-id="${asset.id}"`)}${button("Query","open-sql","ghost",`data-id="${asset.id}"`)}${button("Notebook","open-notebook","ghost",`data-id="${asset.id}"`)}${button("Pipeline","add-to-pipeline","ghost",`data-id="${asset.id}"`)}${button("More","local-more","ghost",`data-id="${asset.id}"`)}</div></td></tr>`;})))}<div class="card-grid two" style="margin-top:10px">${card("Snapshot retention", selected?`<div class="tree-card"><div class="tree-card-title">CURRENT · ${escapeHtml(selected.fullName)}</div><div class="tree-card-children"><div class="tree-card-child">${escapeHtml(selected.localStatus||"Ready")} · ${escapeHtml(selected.localUpdated||selected.updated)}</div><div class="tree-card-child">PREVIOUS · expires in 18h 42m · retained for refresh recovery</div></div></div>`:`<div class="empty-state compact"><strong>No local snapshot selected</strong><p>Materialize or generate a local dataset to see retention details.</p></div>`, { action: selected?button("Refresh local copy","refresh-local","ghost",`data-id="${selected.id}"`):button("Materialize data","start-movement","ghost") })}${card("Local processing", `<div class="pill-row">${["DuckDB SQL", "Python", "PySpark", "Notebook", "Visual pipeline"].map(tag=>badge(tag, "blue")).join("")}</div><p class="tiny">LOCAL data can be reused across SQL, notebooks and pipeline definitions. Remote permissions and export policies remain distinct.</p>`, { action: screenButton("Open SQL Workspace", "sql-workspace", "ghost") })}</div></div>`;
}

function renderMovement(state) {
  const steps = ["Source", "Destination", "Scope", "Columns", "Format", "Governance", "Review", "Transfer"];
  const asset = getAsset(state);
  const blocked = asset.exportAllowed === false;
  const config = state.movementConfig;
  let content = "";
  if (state.movementStep === 1) content = `<div class="form-grid">${selectField("Remote source", "movement-source", asset.id, state.assets.filter(a=>a.environment !== "LOCAL").map(a=>a.id))}${selectField("Environment", "movement-environment", asset.environment, ["DEV", "PROD"])}${selectField("Catalog", "movement-catalog", asset.fullName.split(".")[0], [asset.fullName.split(".")[0], "customer", "sales", "finance", "risk"])}</div>`;
  else if (state.movementStep === 2) content = `<div class="form-grid">${selectField("Destination", "movement-destination", config.destination, ["Local workspace", "Customer Ingestion Lab", "Project storage"])}${selectField("Runtime profile", "movement-runtime", "Local Parquet store", ["Local Parquet store", "Local DuckDB database"])}<div class="notice info" style="grid-column:1/-1"><span>ⓘ</span><div><strong>Local-first transfer simulation</strong>This prototype does not extract or copy real enterprise data.</div></div></div>`;
  else if (state.movementStep === 3) content = `<div class="form-grid">${selectField("Transfer scope", "movement-mode", config.mode, ["Full table", "Sample rows", "Filtered rows"])}${field("Row sample size", "movement-rows", 50000, "number", "Only used for Sample rows.")}${field("Filter expression", "movement-filter", "transaction_date >= CURRENT_DATE - 30", "text", "Used only for Filtered rows.")}${field("Estimated source size", "movement-estimate", asset.size, "text", "Estimate from catalog metadata.")}</div>`;
  else if (state.movementStep === 4) content = `<div class="pill-row">${asset.schema.map(([name,type])=>`<label class="pill-select"><input type="checkbox" data-column="${escapeHtml(name)}" ${config.columns.includes(name)?"checked":""}> <span class="mono">${escapeHtml(name)}</span> · ${escapeHtml(type)}</label>`).join("")}</div><p class="tiny">${config.columns.length} columns selected.</p>`;
  else if (state.movementStep === 5) content = `<div class="form-grid">${selectField("Local format", "movement-format", config.format, ["Parquet", "CSV", "JSON"])}${selectField("Compression", "movement-compression", "ZSTD", ["ZSTD", "Snappy", "None"])}${selectField("Partitioning", "movement-partition", "transaction_date", ["transaction_date", "customer_id", "None"])}</div>`;
  else if (state.movementStep === 6) content = blocked ? `<div class="notice error"><span>⛨</span><div><strong>Local export is blocked by policy</strong>Remote read permission does not grant local export. This asset is Restricted and requires steward approval. The simulated transfer cannot proceed.</div></div><p class="tiny">Request access through the Data Governance workflow. No transfer has started.</p>` : `<div class="notice success"><span>✓</span><div><strong>Local export allowed</strong>Classification: ${escapeHtml(asset.classification)} · Dataset contains no direct identifiers in selected fields.</div></div><label class="check-row" style="margin-top:10px"><input type="checkbox" data-model="movement-ack" checked> I understand this local dataset remains subject to workspace governance.</label>`;
  else if (state.movementStep === 7) content = `<div class="settings-row"><div><strong>Source</strong><small>${escapeHtml(asset.fullName)} · ${asset.environment}</small></div>${badge(asset.classification, asset.classification === "Restricted"?"red":"")}</div><div class="settings-row"><div><strong>Destination</strong><small>${escapeHtml(config.destination)} · ${escapeHtml(config.format)}</small></div>${badge("LOCAL", "green")}</div><div class="settings-row"><div><strong>Data scope</strong><small>${escapeHtml(config.mode)} · ${config.columns.length} of ${asset.schema.length} columns</small></div>${badge(asset.rows.toLocaleString()+" rows")}</div><div class="notice info" style="margin-top:10px"><span>ⓘ</span><div>This is a deterministic mock operation. No remote calls or data transfers will occur.</div></div>`;
  else content = `<div class="empty-state"><strong>Transfer monitor</strong><p>Progress appears in Operations Center. Open the resulting dataset when the simulation completes.</p></div>`;
  return `<div class="page">${pageHead("Data Movement", "Materialize authorized remote data into a reusable LOCAL dataset.", "", "DISCOVER / LOCAL-FIRST MOVEMENT")}<div class="wizard-steps">${steps.map((step,i)=>`<div class="wizard-step ${state.movementStep === i+1 ? "active" : state.movementStep > i+1 ? "done" : ""}"><span>${state.movementStep > i+1 ? "✓" : i+1}</span>${step}</div>`).join("")}</div>${card(`${steps[state.movementStep-1]} · ${state.movementStep} of ${steps.length}`, content, { action: badge(blocked && state.movementStep >= 6 ? "Policy review" : "Simulated workflow", blocked && state.movementStep >=6 ? "red":"blue") })}<div class="wizard-footer"><button class="button secondary" data-action="movement-back" ${state.movementStep === 1 ? "disabled" : ""}>← Back</button><div class="toolbar">${button("Cancel", "cancel-movement", "ghost")}${state.movementStep < 7 ? `<button class="button primary" data-action="movement-next" ${blocked && state.movementStep >= 6 ? "disabled" : ""}>Continue →</button>` : button("Confirm simulated transfer", "run-materialization", "primary", blocked ? "disabled" : "")}</div></div></div>`;
}

function renderLabGallery(state) {
  const query=state.labSearch.toLowerCase();
  const selected=labTemplates.filter(lab=>(!query||`${lab.name} ${lab.description} ${lab.tags.join(" ")} ${lab.components.join(" ")}`.toLowerCase().includes(query))&&(state.labCategory==="All categories"||lab.tags.some(tag=>tag.toLowerCase().includes(state.labCategory.toLowerCase()))||lab.components.some(component=>component.toLowerCase().includes(state.labCategory.replace(/s$/i,"").toLowerCase()))));
  return `<div class="page">${pageHead("Development Labs", "Choose a reproducible local environment with schemas, synthetic data and service behavior ready for engineering.", button(`${icon("plus",12)} Compose a custom Lab`, "create-custom-lab", "primary"), "BUILD / DEVELOPMENT LABS")}<div class="screen-filter"><input class="search-input" placeholder="Search Lab templates…" data-filter="labs" value="${escapeHtml(state.labSearch)}"><select class="search-input" data-lab-category>${["All categories","Databases","Streaming","APIs","Storage","Processing"].map(category=>`<option ${state.labCategory===category?"selected":""}>${category}</option>`).join("")}</select><span class="badge blue">All services are simulated locally</span></div><div class="card-grid" style="margin-top:10px">${selected.map((lab,i)=>`<article class="workspace-card"><div class="toolbar"><span class="row-icon ${i===7?"amber":""}">${["▦","◉","⌁","◇","▤","⚙","◈","⊕","＋"][labTemplates.indexOf(lab)]}</span>${lab.tags.map(tag=>badge(tag,"blue")).join("")}</div><h3>${escapeHtml(lab.name)}</h3><p>${escapeHtml(lab.description)}</p><div class="section-heading"><h2>Components</h2><span class="tiny">${escapeHtml(lab.resources)}</span></div><div class="pill-row">${lab.components.map(c=>badge(c)).join("") || `<span class="tiny">Choose from 20+ components</span>`}</div><div class="card-foot"><span class="tiny">Local resource estimate</span><button class="button secondary" data-action="use-lab-template" data-id="${lab.id}">Customize →</button></div></article>`).join("")||`<div class="empty-state"><strong>No templates match</strong><p>Adjust the search or category.</p></div>`}</div><div class="notice info" style="margin-top:11px"><span>ⓘ</span><div><strong>Compose across service types</strong>Labs can combine databases, event streams, mock APIs, storage, processing engines and supporting services. Selecting a template never provisions containers.</div></div></div>`;
}

function renderLabComposer(state) {
  const components=state.customComponents||[];const selected=state.selectedComponent;const settings=selected!==null?state.componentSettings[selected]||{}:{};const connections=state.componentConnections||[];
  const typeOf=name=>name.includes("Kafka")||name.includes("Producer")?"STREAMING":name.includes("API")||name.includes("GraphQL")||name.includes("Webhook")?"API":name.includes("SQL")||name.includes("Oracle")||name.includes("Postgre")||name.includes("MySQL")||name.includes("Mongo")?"DATABASE":name.toLowerCase().includes("storage")||name.includes("Filesystem")||name.includes("File")?"STORAGE":"PROCESSING";
  let specific="";
  if(selected!==null&&components[selected]){
    const attr=(label,key,value,type="text")=>`<div class="field"><label>${label}</label><input type="${type}" value="${escapeHtml(value??"")}" data-component-property="${key}" data-component-index="${selected}"></div>`;
    const choice=(label,key,value,options)=>`<div class="field"><label>${label}</label><select data-component-property="${key}" data-component-index="${selected}">${options.map(option=>`<option ${value===option?"selected":""}>${option}</option>`).join("")}</select></div>`;
    const category=typeOf(components[selected]);
    specific=category==="DATABASE"?`${attr("Database", "database", settings.database)}${attr("Schema", "schema", settings.schema)}${attr("Seed rows", "seedRows", settings.seedRows,"number")}`:category==="STREAMING"?`${attr("Topic", "topic", settings.topic)}${attr("Partitions", "partitions", settings.partitions,"number")}${choice("Event format", "eventFormat", settings.eventFormat,["Avro","Protobuf","JSON Schema"])}`:category==="API"?`${attr("Base path", "basePath", settings.basePath)}${choice("HTTP method", "method", settings.method,["GET","POST","PUT","GraphQL query"])}${attr("Response status", "responseStatus", settings.responseStatus,"number")}`:category==="STORAGE"?`${attr("Bucket / directory", "bucket", settings.bucket)}${choice("File format", "fileFormat", settings.fileFormat,["Parquet","CSV","JSON","Avro"])}${attr("Partition key", "partitionKey", settings.partitionKey)}`:`${choice("Processing runtime", "runtime", settings.runtime,["PySpark Local","Python Local","DuckDB Local"])}${attr("Worker count", "workers", settings.workers,"number")}`;
  }
  return `<div class="page">${pageHead("Lab Composer", "Build a local development topology from independent service components.", `${button("Validate topology", "validate-lab")}${button("Save Lab", "save-lab", "primary")}`, "BUILD / LAB COMPOSER")}<div class="split-layout" style="grid-template-columns:210px minmax(0,1fr)"><div>${card("Component catalog",componentCatalog.map(category=>`<div class="section-heading"><h2>${category.category}</h2></div>${category.items.map(item=>`<button class="palette-item" data-action="add-component" data-name="${escapeHtml(item)}"><span>＋</span>${escapeHtml(item)}</button>`).join("")}`).join(""))}</div><div>${card("Topology canvas", `<div class="lab-topology">${components.map((name,i)=>`<button class="service-node ${state.selectedComponents?.includes(i)?"selected":""}" data-action="select-component" data-index="${i}"><span class="eyebrow">${typeOf(name)}</span><strong>${escapeHtml(name)}</strong><small>${escapeHtml(state.componentSettings[i]?.endpoint||"local service")}</small><span class="node-health">● Configurable · simulated</span></button>`).join("")||`<div class="empty-state"><span class="empty-icon">⌂</span><strong>Start with an empty Lab</strong><p>Add databases, streams, APIs, storage and processing components from the catalog.</p></div>`}</div>${connections.length?`<div class="connection-list">${connections.map(([from,to])=>`<span class="connection-chip">${escapeHtml(components[from]||"Service")} → ${escapeHtml(components[to]||"Service")}</span>`).join("")}</div>`:""}<div class="settings-row"><div><strong>${components.length} components · ${connections.length} connections</strong><small>Select two services, then connect them. Components stay local in this mock.</small></div><div class="toolbar">${button("Connect selected", "connect-components")}${button("Remove", "remove-component", "danger")}</div></div>`, { action: badge("LOCAL · simulated", "green") })}${card("Selected component configuration", selected!==null&&components[selected]?`<div class="form-grid"><div class="field"><label>Service name</label><input value="${escapeHtml(components[selected])}" data-component-property="name" data-component-index="${selected}"></div><div class="field"><label>Behavior profile</label><select data-component-property="profile" data-component-index="${selected}">${["Standard demo","Slow response","Intermittent failure","Schema drift"].map(profile=>`<option ${settings.profile===profile?"selected":""}>${profile}</option>`).join("")}</select></div><div class="field"><label>Environment</label><input value="LOCAL" disabled></div><div class="field"><label>Service endpoint</label><input value="${escapeHtml(settings.endpoint||"localhost:8080")}" data-component-property="endpoint" data-component-index="${selected}"></div>${specific}</div><div class="toolbar" style="margin-top:9px">${button("Open schema designer", "navigate-schema")}${button("Configure mock behavior", "navigate-mock-behavior")}</div>`:`<div class="empty-state compact"><strong>No component selected</strong><p>Select a service node to configure its schema, contracts and behavior.</p></div>`)}</div></div><div class="toolbar" style="margin-top:10px">${screenButton("Design schemas", "schema-designer")}${screenButton("Configure mock behavior", "mock-behavior")}${screenButton("Resource configuration", "lab-resources")}</div></div>`;
}

function renderSchemaDesigner(state) {
  const schema = state.schemas[0];
  return `<div class="page">${pageHead("Schema & Contract Designer", "Define structures for databases, event topics, API routes and file formats.", `${button("Import sample", "import-schema")}${button(`${icon("plus",12)} Add field`, "add-schema-field", "primary")}`, "BUILD / LAB SCHEMA")}<div class="toolbar" style="margin-bottom:10px">${selectField("Component", "schemaComponent", state.schemaComponent||"SQL Server", ["SQL Server", "Oracle", "Kafka", "REST API", "Filesystem", "MongoDB"])}<div class="segmented"><button class="segment active" data-action="schema-mode" data-mode="visual">Visual design</button><button class="segment" data-action="schema-mode" data-mode="import">Import schema</button><button class="segment" data-action="schema-mode" data-mode="catalog">From catalog</button></div><button class="button secondary" data-action="schema-parse">Validate structure</button></div><div class="split-layout"><div>${card(`${escapeHtml(schema.table)} · v3`, table(["Field", "Data type", "Nullable", "Constraint / description", ""], schema.fields.map((row,i)=>`<tr><td><input class="input mono" style="min-width:100px" value="${escapeHtml(row[0])}" data-schema-field="${i}" data-col="0"></td><td><select class="input mono" data-schema-field="${i}" data-col="1">${["STRING","INTEGER","BIGINT","DECIMAL(12,2)","BOOLEAN","DATE","TIMESTAMP","JSON"].map(type=>`<option ${row[1]===type?"selected":""}>${type}</option>`).join("")}</select></td><td><select class="input" data-schema-field="${i}" data-col="2">${["No","Yes"].map(v=>`<option ${row[2]===v?"selected":""}>${v}</option>`).join("")}</select></td><td><input class="input" value="${escapeHtml(row[3])}" data-schema-field="${i}" data-col="3"></td><td><button class="icon-button" data-action="delete-schema-field" data-index="${i}" aria-label="Remove field">×</button></td></tr>`)))}<div class="toolbar" style="margin-top:9px">${button("Add primary key", "add-primary-key")}${button("Add relationship", "add-relationship")}${button("Save schema", "save-schema", "primary")}</div></div>${card("Contract rules", `<div class="settings-row"><div><strong>Primary key unique</strong><small>customer_id · not null</small></div><button class="switch on" data-action="toggle-switch" aria-label="Toggle primary key rule"></button></div><div class="settings-row"><div><strong>Email format</strong><small>Valid email when present</small></div><button class="switch on" data-action="toggle-switch" aria-label="Toggle email rule"></button></div><div class="settings-row"><div><strong>PII classification</strong><small>email · masked in synthetic output</small></div>${badge("Sensitive", "amber")}</div><div class="section-heading"><h2>Relationships</h2>${button("+ Add", "add-relationship", "ghost")}</div><div class="tree-card"><div class="tree-card-title">Customers.customer_id <span class="tiny">PK</span></div><div class="tree-card-child">→ Addresses.customer_id <span class="tiny">FK</span></div></div>`, { action: badge("Valid", "green") })}</div><div class="card-grid two" style="margin-top:10px">${card("Schema import formats", `<div class="pill-row">${["SQL DDL", "JSON Schema", "Avro", "Protobuf", "OpenAPI", "JSON example", "CSV/Parquet metadata"].map(item=>badge(item,"blue")).join("")}</div><p class="tiny">Bundled sample schemas are supported. Arbitrary format parsing is not implemented in this frontend mock.</p>`)}</div></div>`;
}

function renderMockBehavior(state) {
  const config=state.mockSettings;const service=state.mockService||state.customComponents?.[0]||"SQL Server";const value=String(service).toLowerCase();
  const category=value.includes("kafka")||value.includes("stream")?"streaming":value.includes("api")||value.includes("graphql")?"api":value.includes("storage")||value.includes("file")?"storage":"relational";
  const selectedProfile=state.mockProfile||category;
  const profiles=["relational","streaming","api","storage"];
  const services=[...new Set([...(state.customComponents||[]),"SQL Server","Kafka","REST API","Filesystem"])];
  const activeFields=category==="streaming"?`${field("Messages per second","mockSettings.rate",config.rate,"number")}${field("Late events (%)","mockSettings.lateEvents",config.lateEvents,"number")}${selectField("Event format","mockSettings.eventFormat",config.eventFormat||"Avro",["Avro","Protobuf","JSON Schema"])}${selectField("Duplicate behavior","mockSettings.duplicatesMode",config.duplicatesMode||"Deduplicate by event key",["Deduplicate by event key","Allow duplicates","Inject duplicate burst"])}`:category==="api"?`${field("Response delay (ms)","mockSettings.delay",config.delay,"number")}${field("HTTP failure rate (%)","mockSettings.httpFailure",config.httpFailure,"number")}${selectField("Pagination","mockSettings.pagination",config.pagination||"Cursor-based",["Cursor-based","Offset","No pagination"])}${selectField("Auth behavior","mockSettings.auth",config.auth||"Valid token",["Valid token","Expired token","Intermittent 401"])}`:category==="storage"?`${field("Files to generate","mockSettings.rows",config.rows,"number")}${selectField("File format","mockSettings.fileFormat",config.fileFormat||"Parquet",["Parquet","CSV","JSON","Avro"])}${selectField("File arrival","mockSettings.fileArrival",config.fileArrival||"Hourly batches",["Hourly batches","One daily file","Late arrival","Empty file scenario"])}`:`${field("Rows","mockSettings.rows",config.rows,"number")}${field("Null percentage","mockSettings.nullPercent",config.nullPercent,"number")}${field("Duplicate rate (%)","mockSettings.duplicates",config.duplicates,"number")}${selectField("Relationship behavior","mockSettings.relationships",config.relationships||"Preserve foreign keys",["Preserve foreign keys","Allow orphans","Inject violations"])}${selectField("Incremental changes","mockSettings.incremental",config.incremental||"Daily updates",["Daily updates","No changes","Late updates","Deletes and updates"])}`;
  const scenarios=["Constraint violation","Duplicate event","Schema drift","Empty file","429 rate limit","Auth failure","Delayed response"];
  return `<div class="page">${pageHead("Mock Data & Behavior", "Make each local service behave like a realistic engineering dependency.", `${button("Preview scenarios", "preview-mock")}${button("Save behavior", "save-mock", "primary")}`, "BUILD / LAB SIMULATION")}<div class="screen-filter"><div class="field"><label>Service</label><select data-model="mock-service">${services.map(name=>`<option ${service===name?"selected":""}>${escapeHtml(name)}</option>`).join("")}</select></div><div class="segmented">${profiles.map(profile=>`<button class="segment ${selectedProfile===profile?"active":""}" data-action="mock-profile" data-value="${profile}">${profile[0].toUpperCase()+profile.slice(1)}</button>`).join("")}</div><span class="badge blue">${category.toUpperCase()} behavior profile</span></div><div class="split-layout" style="margin-top:10px"><div>${card(`${category==="streaming"?"Stream":category==="api"?"API":category==="storage"?"Storage":"Database"} behavior`, `<div class="form-grid">${activeFields}</div><div class="notice info" style="margin-top:9px"><span>ⓘ</span><div>Settings apply to ${escapeHtml(service)} in the local mock Lab. No external service is contacted.</div></div>`, { action: badge("Deterministic seed", "blue") })}${card("Failure scenarios", `<div class="pill-row">${scenarios.map(name=>`<label class="pill-select"><input type="checkbox" data-mock-scenario="${escapeHtml(name)}" ${(state.mockScenarios||[]).includes(name)?"checked":""}>${escapeHtml(name)}</label>`).join("")}</div>`, { action: badge(`${(state.mockScenarios||[]).length} enabled`, "amber") })}</div><div>${card("Scenario preview", `<div class="settings-row"><div><strong>Normal service behavior</strong><small>${category==="streaming"?`${config.rate} events/sec · ${config.lateEvents}% late`:category==="api"?`${config.delay} ms response · ${config.httpFailure}% HTTP failure`:category==="storage"?`${Number(config.rows).toLocaleString()} files · ${config.fileFormat||"Parquet"}`:`${Number(config.rows).toLocaleString()} rows · ${config.nullPercent}% null rate`}</small></div>${badge("Default", "green")}</div><div class="settings-row"><div><strong>Injected scenarios</strong><small>${(state.mockScenarios||[]).join(" · ")||"None selected"}</small></div>${badge((state.mockScenarios||[]).length?"Enabled":"Disabled",(state.mockScenarios||[]).length?"amber":"")}</div><div class="settings-row"><div><strong>Preview generated</strong><small>${escapeHtml(state.mockPreview||"No preview run in this session")}</small></div>${button("Preview", "preview-mock", "ghost")}</div><div class="section-heading"><h2>Representative output</h2></div>${table(category==="streaming"?["event_id","event_time","event_type","scenario"]:category==="api"?["method","path","status","response"]:category==="storage"?["file","format","records","arrival"]:["customer_id","created_at","customer_tier","scenario"],category==="streaming"?[`<tr><td>E-584201</td><td>09:18:32</td><td>payment</td><td>${badge("On time","green")}</td></tr>`,`<tr><td>E-584202</td><td>08:57:11</td><td>login</td><td>${badge("Late +21m","amber")}</td></tr>`]:category==="api"?[`<tr><td>GET</td><td>/v1/customers/C-008421</td><td>200</td><td>Profile response</td></tr>`,`<tr><td>GET</td><td>/v1/customers/C-008422</td><td>${config.httpFailure?"504":"200"}</td><td>${config.httpFailure?"Timeout scenario":"Profile response"}</td></tr>`]:category==="storage"?[`<tr><td>customers/part-0001</td><td>${escapeHtml(config.fileFormat||"Parquet")}</td><td>10,000</td><td>09:00</td></tr>`,`<tr><td>customers/part-0002</td><td>${escapeHtml(config.fileFormat||"Parquet")}</td><td>2,842</td><td>09:15</td></tr>`]:[`<tr><td>C-008421</td><td>09:18:32</td><td>Gold</td><td>${badge("On time","green")}</td></tr>`,`<tr><td>C-008422</td><td>08:57:11</td><td>Silver</td><td>${badge("Late +21m","amber")}</td></tr>`])}`, { action: badge("Simulated", "amber") })}${card("Applied configuration", `<div class="settings-row"><div><strong>${escapeHtml(service)}</strong><small>${escapeHtml(state.mockProfile||category)} profile · ${escapeHtml(state.mockSavedAt||"Not saved")}</small></div>${badge("LOCAL","green")}</div><p class="tiny">Preview and save actions update this browser's mock state only.</p>`)}</div></div></div>`;
}

function renderLabResources(state) {
  const config=state.resourceSettings; const lab=getLab(state);
  return `<div class="page">${pageHead("Lab Resources", "Review the local resource envelope, ports, dependencies and reproducible service manifest.", `${button("Validate resources", "validate-lab")}${button("Save configuration", "save-lab", "primary")}`, "BUILD / RESOURCE CONFIGURATION")}<div class="split-layout"><div class="form-stack">${card("Resource envelope", `<div class="form-grid">${field("CPU cores", "resourceSettings.cpu", config.cpu, "number")}${field("Memory (GB)", "resourceSettings.memory", config.memory, "number")}${field("Storage (GB)", "resourceSettings.storage", config.storage, "number")}${selectField("Network", "resourceSettings.network", config.network, ["Isolated local network", "Host network", "No network"])}</div><div class="notice ${config.memory>14||config.cpu>8?"error":"info"}" style="margin-top:10px"><span>ⓘ</span><div><strong>${config.memory>14||config.cpu>8?"Resource warning":"Within local budget"}</strong>${config.memory>14||config.cpu>8?"This composition may exceed a typical developer laptop budget.":"Estimate reflects selected services and synthetic workload."}</div></div>`, { action: badge(`${lab.components.length} services`) })}${card("Ports and dependencies", table(["Service", "Port", "Depends on", "Startup order"], lab.components.map((component,i)=>`<tr><td>${escapeHtml(component)}</td><td><input class="input mono" value="${component.includes("SQL")?"1433":component.includes("Kafka")?"9092":8080+i}" style="width:70px"></td><td>${i?escapeHtml(lab.components[i-1]):"—"}</td><td>${i+1}</td></tr>`)))}</div><div>${card("Local endpoints", lab.components.map((component,i)=>`<div class="settings-row"><div><strong>${escapeHtml(component)}</strong><small class="mono">${component.includes("SQL")?"sqlserver.local:1433":component.includes("Oracle")?"oracle.local:1521":component.includes("Kafka")?"kafka.local:9092":component.includes("API")?"http://api.local:8080":"localhost:"+(8000+i)}</small></div>${badge("Simulated", "blue")}</div>`).join(""))}${card("Manifest preview", `<pre class="mono-block">name: ${escapeHtml(lab.name)}\nprofile: ${escapeHtml(lab.template)}\nmode: local-simulation\nresources:\n  cpu: ${config.cpu}\n  memory_gb: ${config.memory}\n  storage_gb: ${config.storage}\nservices:\n${lab.components.map((c,i)=>`  - name: ${escapeHtml(c.toLowerCase().replaceAll(" ","-"))}\n    startup_order: ${i+1}\n    simulated: true`).join("\n")}</pre>`, { action: button("Copy manifest", "copy-manifest", "ghost") })}</div></div></div>`;
}

function renderLabCockpit(state) {
  const lab=getLab(state); const running=lab.status === "Running";
  return `<div class="page">${pageHead(lab.name, `${lab.template} · composed local development environment`, `<button class="button ${running?"secondary":"primary"}" data-action="lab-${running?"stop":"start"}">${running?"■ Stop Lab":"▶ Start Lab"}</button>${button("Restart", "lab-restart")}${!running?button("Simulate startup failure", "lab-start-fail", "ghost"):""}${button("Reset", "lab-reset", "ghost")}`, "BUILD / LAB COCKPIT")}<div class="card-grid four">${stat("Lab state", lab.status, "Lifecycle is simulated", "lab", running?"":"")}${stat("Services", lab.components.length, `${lab.health} health`, "database")}${stat("Schemas", lab.schemas.length, "Contracts available", "table")}${stat("Resources", `${state.resourceSettings.cpu} vCPU`, `${state.resourceSettings.memory} GB memory`, "settings")}</div><div class="split-layout" style="margin-top:10px"><div>${card("Service topology", `<div class="lab-topology">${lab.components.map((service,i)=>`<button class="service-node" data-action="select-component" data-index="${i}"><span class="eyebrow">SERVICE ${String(i+1).padStart(2,"0")}</span><strong>${escapeHtml(service)}</strong><small>${escapeHtml(lab.endpoints[i] || "localhost:8080")}</small><span class="node-health">● ${running?"Healthy":"Stopped"}</span></button>`).join("")}</div>`, { action: badge(lab.status, running?"green":"") })}${card("Connection endpoints", lab.endpoints.map(endpoint=>`<div class="settings-row"><div><strong class="mono">${escapeHtml(endpoint)}</strong><small>Local network · credentials mocked</small></div>${running?badge("Reachable","green"):badge("Offline")}</div>`).join(""), { action: button("Copy connection details", "copy-endpoints", "ghost") })}</div><div>${card("Component health", lab.components.map(component=>`<div class="settings-row"><div><strong>${escapeHtml(component)}</strong><small>Behavior profile · standard demo</small></div>${badge(running?"Healthy":"Stopped",running?"green":"")}</div>`).join(""))}${card("Schemas and data", `<div class="compact-list">${lab.schemas.map(schema=>`<div class="compact-row"><span class="row-icon">▦</span><div class="row-main"><strong>${escapeHtml(schema)}</strong><small>Contract v3 · synthetic seed</small></div>${screenButton("Open", "schema-designer", "ghost")}</div>`).join("")}</div>`, { action: screenButton("Mock behavior", "mock-behavior", "ghost") })}${card("Recent logs", `<pre class="mono-block">${lab.logs.map(escapeHtml).join("\n")}</pre>`)}</div></div><div class="toolbar" style="margin-top:10px">${button("Open schema", "navigate-schema")}${button("Open connection", "copy-endpoints")}${screenButton("Open notebook", "notebook-studio")}${screenButton("Open pipeline", "pipeline-studio")}</div></div>`;
}

function renderNotebook(state) {
  const notebook=getNotebook(state);
  return `<div class="page">${pageHead(notebook.name, `${notebook.cells.length} cells · Autosaved to workspace artifact · ${notebook.runtime}`, `<select class="search-input" data-model="notebook-runtime">${["Python Local","DuckDB Local","PySpark Local","Databricks Connected — Mock"].map(r=>`<option ${notebook.runtime===r?"selected":""}>${r}</option>`).join("")}</select>${button("＋ Code", "add-code-cell")}${button("＋ Markdown", "add-markdown-cell")}${button("Run all", "run-notebook", "primary")}${button("Save", "save-notebook")}`, "BUILD / NOTEBOOK STUDIO")}<div class="split-layout" style="grid-template-columns:minmax(0,1fr) 220px"><div>${notebook.cells.map((cell,i)=>`<article class="notebook-cell"><div class="cell-head"><span class="cell-counter">[${cell.output?"✓":" "}] ${String(i+1).padStart(2,"0")}</span><span>${cell.type === "markdown" ? "Markdown" : cell.type === "sql" ? "SQL" : "Python"} cell</span><span class="cell-spacer"></span><button data-action="run-notebook-cell" data-id="${cell.id}">▶ Run</button><button data-action="move-cell" data-id="${cell.id}" data-direction="up" aria-label="Move cell up">↑</button><button data-action="move-cell" data-id="${cell.id}" data-direction="down" aria-label="Move cell down">↓</button><button data-action="remove-cell" data-id="${cell.id}" aria-label="Remove cell">×</button></div><textarea class="cell-code" data-cell-id="${cell.id}" aria-label="${cell.type} cell">${escapeHtml(cell.source)}</textarea><div class="cell-output">${escapeHtml(cell.output || "")}</div></article>`).join("")}<button class="button secondary" data-action="add-code-cell">＋ Add code cell</button> ${button("Add markdown", "add-markdown-cell")}</div><div>${card("Notebook outline", `<div class="compact-list">${notebook.cells.map((cell,i)=>`<button class="explorer-link" data-action="scroll-cell" data-id="${cell.id}"><span class="link-icon">${cell.type==="markdown"?"¶":"▣"}</span>Cell ${i+1} · ${escapeHtml(cell.source.split("\n")[0].slice(0,22))}</button>`).join("")}</div>`, { action: badge("IPYNB concept", "blue") })}${card("Runtime", `<div class="settings-row"><div><strong>${escapeHtml(notebook.runtime)}</strong><small>Session · local simulation</small></div>${badge("Ready","green")}</div><div class="settings-row"><div><strong>Python</strong><small>3.11 · mocked</small></div>${badge("Available","blue")}</div><p class="tiny">No kernel is connected. Known demo cells return deterministic outputs.</p>`, { action: button("Runtime details", "runtime-details", "ghost") })}${card("Data resources", `<div class="settings-row"><div><strong>${escapeHtml(getAsset(state).fullName)}</strong><small>${escapeHtml(getAsset(state).environment)} · ${escapeHtml(getAsset(state).type)}</small></div></div><p class="tiny">Insert a starter query using the selected shared catalog asset.</p>`, { action: button("Insert read cell", "insert-asset-notebook", "ghost") })}${card("Notebook metadata", `<div class="settings-row"><div><strong>Owner</strong><small>Henrique Silva</small></div></div><div class="settings-row"><div><strong>Workspace</strong><small>${escapeHtml(getWorkspace(state).name)}</small></div></div><div class="settings-row"><div><strong>Portable format</strong><small>.ipynb conceptual export</small></div></div>`)}</div></div></div>`;
}

function renderSqlResult(result) {
  if(!result) return `<div class="empty-state"><span class="empty-icon">⌁</span><strong>Run a query to inspect results</strong><p>Responses are deterministic and use the shared demo catalog.</p></div>`;
  return `<div class="result-toolbar"><span class="tiny">${result.rows.length} rows returned · ${escapeHtml(result.duration)} · ${escapeHtml(result.route)}</span>${badge(result.route==="LOCAL"?"DuckDB Local":"Databricks SQL · Mock",result.route==="LOCAL"?"green":"amber")}</div><div class="table-wrap"><table class="data-table"><thead><tr>${result.columns.map(value=>`<th>${escapeHtml(value)}</th>`).join("")}</tr></thead><tbody>${result.rows.map(row=>`<tr>${row.map(value=>`<td>${escapeHtml(value)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
}

function renderSql(state) {
  return `<div class="page">${pageHead("SQL Workspace", `${state.sql.route === "LOCAL" ? "DuckDB Local" : state.sql.route === "DATABRICKS" ? "Databricks SQL · Mock" : "AUTO route"} · ${state.sql.history.length} recent queries`, `<select class="search-input" data-model="sql-route"><option ${state.sql.route==="AUTO"?"selected":""}>AUTO</option><option ${state.sql.route==="LOCAL"?"selected":""}>LOCAL</option><option ${state.sql.route==="DATABRICKS"?"selected":""}>DATABRICKS</option></select>${button("Explain", "explain-sql")}${button("Run query", "run-sql", "primary")}`, "BUILD / ANALYTICS SQL")}<div class="split-layout" style="grid-template-columns:minmax(0,1fr) 200px"><div><div class="editor-shell"><div class="editor-topline"><span class="row-icon">⌘</span><span>query_customer_revenue.sql</span><span class="toolbar-divider"></span><span class="badge blue">${escapeHtml(state.sql.route === "AUTO" ? "AUTO" : state.sql.route)}</span><span class="toolbar-divider"></span><span>Read-only demo engine</span><span style="margin-left:auto">UTF-8</span></div><div class="editor-buffer"><div class="line-numbers">${state.sql.text.split("\n").map((_,i)=>i+1).join("<br>")}</div><textarea id="sql-editor" data-model="sql.text" aria-label="SQL editor" spellcheck="false">${escapeHtml(state.sql.text)}</textarea></div></div><div class="result-panel"><div class="result-toolbar"><strong>Results</strong></div><div id="sql-result-body">${renderSqlResult(state.sqlResult)}</div></div></div><div>${card("Catalog explorer", `<div class="explorer-search"><span>⌕</span><input placeholder="Find a table" data-filter="sql-assets"></div>${state.assets.map(a=>`<button class="tree-row ${a.environment==="LOCAL"?"selected":""}" data-action="insert-asset-sql" data-id="${a.id}"><span class="tree-dot ${a.environment==="LOCAL"?"local":""}"></span>${escapeHtml(a.name)}<small>${a.environment}</small></button>`).join("")}`, { action: badge(`${state.assets.length} assets`, "blue") })}${card("Query history", `<div class="compact-list">${state.sql.history.map((query,i)=>`<button class="explorer-link" data-action="load-query" data-index="${i}"><span class="link-icon">◷</span><span class="mono" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(query.slice(0,34))}</span></button>`).join("")}</div>`, { action: button("Clear history", "clear-query-history", "ghost") })}${card("Execution context", `<div class="settings-row"><div><strong>Engine</strong><small>${state.sql.route==="DATABRICKS"?"Databricks SQL · mock":state.sql.route==="LOCAL"?"DuckDB Local":"AUTO route"}</small></div>${badge(state.sql.route==="DATABRICKS"?"Mock":state.sql.route==="LOCAL"?"Ready":"Auto",state.sql.route==="DATABRICKS"?"amber":"green")}</div><div class="settings-row"><div><strong>Tab environment</strong><small>Object scope stays independent of runtime selection</small></div>${badge(state.activeTabEnvironment||state.environment,"blue")}</div></div>`)}</div></div></div>`;
}

function renderPipeline(state) {
  const pipeline=getPipeline(state); const selected=pipeline.nodes.find(n=>n.id===state.selectedNode) || pipeline.nodes[0];
  const graphEdges=pipeline.edges || pipeline.nodes.slice(1).map((node,index)=>[pipeline.nodes[index].id,node.id]);
  const compactDesktop=typeof window!=="undefined"&&window.innerWidth>=1511&&window.innerWidth<2300;
  const graphScale=compactDesktop ? .82 : 1;
  const canvasWidth=Math.max(compactDesktop?960:1120,...pipeline.nodes.map(node=>node.x*graphScale+200));
  const edges=graphEdges.map(([fromId,toId])=>{const from=pipeline.nodes.find(node=>node.id===fromId),to=pipeline.nodes.find(node=>node.id===toId);if(!from||!to)return "";const x1=(from.x+170)*graphScale,y1=from.y+38,x2=to.x*graphScale,y2=to.y+38,curve=48*graphScale;return `<path class="pipeline-edge" d="M ${x1} ${y1} C ${x1+curve} ${y1}, ${x2-curve} ${y2}, ${x2} ${y2}"/>`;}).join("");
  const validation=state.pipelineValidation;
  return `<div class="page">${pageHead(pipeline.name, `${pipeline.description} · ${pipeline.nodes.length} nodes · Logical pipeline`, `${button("Validate", "validate-pipeline")}${button("Preview order", "preview-pipeline-order")}${button("Run pipeline", "run-pipeline", "primary")}`, "BUILD / PIPELINE STUDIO")}<div class="canvas-layout"><aside class="canvas-palette"><h3 class="canvas-title">Components</h3>${pipelineNodeTypes.map(type=>`<button class="palette-item" data-action="add-pipeline-node" data-type="${escapeHtml(type)}"><span>＋</span>${escapeHtml(type)}</button>`).join("")}</aside><div class="pipeline-canvas" id="pipeline-canvas"><div class="pipeline-canvas-inner" style="width:max(100%, ${canvasWidth}px)"><svg class="pipeline-edges" width="${canvasWidth}" height="410" viewBox="0 0 ${canvasWidth} 410"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#8c774e"/></marker></defs>${edges}</svg>${pipeline.nodes.map(node=>`<div class="pipeline-node ${selected?.id===node.id?"selected":""}" draggable="true" data-action="select-pipeline-node" data-id="${escapeHtml(node.id)}" style="left:${node.x*graphScale}px;top:${node.y}px"><span class="node-type">${escapeHtml(node.type)}</span><strong>${escapeHtml(node.title)}</strong><small>${escapeHtml(node.subtitle)}</small></div>`).join("")||`<div class="empty-state compact pipeline-empty"><strong>Start with a source</strong><p>Add components from the palette. Connect adjacent nodes from their properties panel.</p></div>`}</div></div><aside class="canvas-inspector"><h3 class="canvas-title">Properties</h3>${selected?`<div class="form-stack"><div class="field"><label>Node name</label><input value="${escapeHtml(selected.title)}" data-node-property="title" data-node-id="${escapeHtml(selected.id)}"></div><div class="field"><label>Type</label><select data-node-property="type" data-node-id="${escapeHtml(selected.id)}">${pipelineNodeTypes.map(type=>`<option ${selected.type===type?"selected":""}>${type}</option>`).join("")}</select></div><div class="field"><label>Configuration</label><textarea data-node-property="subtitle" data-node-id="${escapeHtml(selected.id)}">${escapeHtml(selected.subtitle)}</textarea></div><div class="notice ${selected.type==="Data Quality"?"error":"info"}"><span>${selected.type==="Data Quality"?"!":"ⓘ"}</span><div>${selected.type==="Data Quality"?"Required field customer_tier is missing from source schema.":"Select a node to edit its inputs, transformations and output contract."}</div></div><div class="toolbar">${button("Connect next", "connect-pipeline-node", "secondary", `data-id="${escapeHtml(selected.id)}"`)}${button("Remove node", "remove-pipeline-node", "danger", `data-id="${escapeHtml(selected.id)}"`)}</div></div>`:`<p class="tiny">Select a pipeline node.</p>`}</aside></div><div class="toolbar" style="margin-top:9px">${badge("Graph editor · draggable nodes", "blue")}${badge(`${graphEdges.length} dependency edges`)}${screenButton("Configure orchestration", "orchestration")}${screenButton("Target preview", "artifact-preview")}</div>${graphEdges.length?`<div class="connection-list">${graphEdges.map(([from,to])=>`<span class="connection-chip">${escapeHtml(pipeline.nodes.find(n=>n.id===from)?.title||from)} → ${escapeHtml(pipeline.nodes.find(n=>n.id===to)?.title||to)}</span>`).join("")}</div>`:""}<div id="pipeline-validation" class="notice ${validation?(validation.broken?"error":"success"):"info"}" style="margin-top:9px"><span>${validation?(validation.broken?"!":"✓"):"ⓘ"}</span><div>${validation?escapeHtml(validation.message):"Validate the graph to check required inputs, cycles and output contracts."}</div></div></div>`;
}

function renderOrchestration(state) {
  const config=state.orchestration;const tasks=config.tasks||[];const edges=config.edges||[];const selectedIds=state.selectedTasks||[];const selectedTask=tasks.find(task=>task.id===state.selectedTaskId);
  return `<div class="page">${pageHead("Orchestration Designer", "Define when logical pipeline steps run, how they depend on each other and how failures are handled.", `${button("Validate workflow", "validate-orchestration")}${button("View target artifact", "navigate-artifact-preview", "primary")}`, "BUILD / ORCHESTRATION")}<div class="split-layout" style="grid-template-columns:minmax(0,1.2fr) minmax(260px,.8fr)"><div>${card("Execution graph", `<div class="lab-topology">${tasks.map((task,index)=>`<button class="service-node ${selectedIds.includes(task.id)?"selected":""}" data-action="select-task" data-id="${escapeHtml(task.id)}"><span class="eyebrow">TASK ${String(index+1).padStart(2,"0")}</span><strong>${escapeHtml(task.name)}</strong><small>${escapeHtml(task.kind||"Pipeline step")}</small><span class="node-health">${edges.filter(edge=>edge[1]===task.id).length?"Dependency":"Entry task"} · ${edges.filter(edge=>edge[0]===task.id).length?"has downstream":"terminal"}</span></button>`).join("")||`<div class="empty-state compact"><strong>No workflow tasks</strong><p>Add tasks to define the execution graph.</p></div>`}</div>${edges.length?`<div class="connection-list">${edges.map(([from,to])=>`<span class="connection-chip">${escapeHtml(tasks.find(task=>task.id===from)?.name||from)} → ${escapeHtml(tasks.find(task=>task.id===to)?.name||to)}</span>`).join("")}</div>`:""}<div class="toolbar" style="margin-top:8px">${button("Add task", "add-orchestration-task")}${button("Add dependency", "add-task-dependency", "secondary", selectedIds.length<2?"disabled":"")}${badge(`${tasks.length} tasks · ${edges.length} dependencies`, "blue")}</div><p class="tiny">Select two task cards in order (source, then target) to create a dependency.</p>`, { action: badge("Technology agnostic", "green") })}${selectedTask?card("Selected task", `<div class="form-stack"><div class="field"><label>Task name</label><input data-task-property="name" data-task-id="${escapeHtml(selectedTask.id)}" value="${escapeHtml(selectedTask.name)}"></div><div class="field"><label>Task behavior</label><select data-task-property="kind" data-task-id="${escapeHtml(selectedTask.id)}">${["Pipeline step","On success","On failure","Conditional","Asset update"].map(kind=>`<option ${selectedTask.kind===kind?"selected":""}>${kind}</option>`).join("")}</select></div></div>`, { action: button("Remove task", "remove-orchestration-task", "danger", `data-id="${escapeHtml(selectedTask.id)}"`) }):""}${card("Schedule and trigger", `<div class="form-grid">${selectField("Trigger type", "orchestration.trigger", config.trigger||"Scheduled", ["Scheduled", "On asset update", "Manual", "Event trigger"])}${field("Schedule", "orchestration.schedule", config.schedule)}${selectField("Timezone", "orchestration.timezone", config.timezone||"UTC", ["UTC", "America/Sao_Paulo", "America/New_York"])}${selectField("Start date", "orchestration.startDate", config.startDate||"Immediately", ["Immediately", "Next scheduled run", "Choose date"])}</div>`)}</div><div>${card("Execution policy", `<div class="form-grid">${field("Retries", "orchestration.retries", config.retries, "number")}${field("Timeout (minutes)", "orchestration.timeout", config.timeout, "number")}${field("Max concurrent runs", "orchestration.concurrency", config.concurrency, "number")}${selectField("Failure behavior", "orchestration.failure", config.failure, ["Stop downstream tasks", "Continue independent tasks", "Retry then alert"])}${selectField("Resource profile", "orchestration.resource", config.resource||"Small · 2 vCPU", ["Small · 2 vCPU", "Medium · 4 vCPU", "Large · 8 vCPU"])}</div>`, { action: badge("Draft", "amber") })}${card("Target adapters", `<div class="form-stack">${["Airflow","Azure Data Factory","Databricks Workflows"].map(target=>`<label class="pill-select"><input type="radio" name="adapter" value="${target}" data-adapter ${state.adapter===target?"checked":""}>${target}</label>`).join("")}</div><div class="notice info" style="margin-top:9px"><span>ⓘ</span><div>Logical task dependencies remain stable while target-specific semantics are previewed.</div></div>`, { action: badge(state.adapter, "blue") })}</div></div></div>`;
}

function renderArtifactPreview(state) {
  const target=state.adapter;const config=state.orchestration;const tasks=config.tasks||[];const edges=config.edges||[];
  const taskId=id=>String(id).replace(/[^a-zA-Z0-9_]/g,"_");
  let preview;
  if(target==="Airflow") {
    const declarations=tasks.map(task=>`    ${taskId(task.id)} = PythonOperator(task_id="${taskId(task.id)}", python_callable=run_${taskId(task.id)})`).join("\n");
    const dependencies=edges.map(([from,to])=>`    ${taskId(from)} >> ${taskId(to)}`).join("\n");
    preview=`from airflow import DAG\nfrom airflow.operators.python import PythonOperator\nfrom datetime import datetime\n\nwith DAG(\n    dag_id="${getPipeline(state).name}",\n    schedule="${config.schedule}",\n    start_date=datetime(2026, 1, 1),\n    catchup=False,\n    max_active_runs=${config.concurrency},\n) as dag:\n${declarations||"    pass"}${dependencies?"\n"+dependencies:""}`;
  } else if(target==="Azure Data Factory") {
    const activities=tasks.map(task=>({name:taskId(task.id),type:task.kind==="Pipeline step"?"ExecutePipeline":"Validation",dependsOn:edges.filter(edge=>edge[1]===task.id).map(([,from])=>({activity:taskId(from),condition:"Succeeded"}))}));
    preview=JSON.stringify({name:getPipeline(state).name,properties:{activities,policy:{retry:config.retries,timeout:`${config.timeout}:00:00`},schedule:config.schedule}},null,2);
  } else {
    const tasksPayload=tasks.map(task=>({task_key:taskId(task.id),notebook_task:{notebook_path:`/workspace/${taskId(task.id)}`},depends_on:edges.filter(edge=>edge[1]===task.id).map(([,from])=>({task_key:taskId(from)}))}));
    preview=JSON.stringify({name:getPipeline(state).name,tasks:tasksPayload,max_concurrent_runs:config.concurrency,schedule:config.schedule},null,2);
  }
  return `<div class="page">${pageHead("Target Adapter & Artifact Preview", "Inspect generated artifacts and target capabilities. Adapter previews are representative, not production compilers.", `${button("Add to artifact review", "add-artifact")}${button("Open PR wizard", "navigate-pr-wizard", "primary")}`, "BUILD / TARGET ADAPTERS")}<div class="screen-filter"><div class="segmented">${["Airflow","Azure Data Factory","Databricks Workflows"].map(targetName=>`<button class="segment ${target===targetName?"active":""}" data-action="set-adapter" data-value="${targetName}">${targetName}</button>`).join("")}</div><span class="badge amber">Preview is simulated</span></div><div class="split-layout" style="margin-top:10px;grid-template-columns:205px minmax(0,1fr)"><div>${card("Generated files", ["customer_incremental_ingest.py","contracts/customer_profile.yaml","notebooks/customer_profile.ipynb","tests/test_customer_ingest.py","README.md"].map((file,i)=>`<button class="explorer-link ${i===0?"active":""}" data-action="select-artifact" data-name="${file}"><span class="link-icon">${i===0?"⌘":"▤"}</span>${file}</button>`).join(""), { action: badge("5 files") })}${card("Compatibility", `<div class="settings-row"><div><strong>Schedules</strong><small>${escapeHtml(config.schedule)}</small></div>${badge("Mapped","green")}</div><div class="settings-row"><div><strong>Retry policy</strong><small>${config.retries} retries · ${config.timeout} minute timeout</small></div>${badge("Supported","green")}</div><div class="settings-row"><div><strong>Conditional branches</strong><small>Target feature mapping</small></div>${badge(target==="Azure Data Factory"?"Mapped":"Supported","amber")}</div><div class="notice" style="margin-top:8px"><span>!</span><div>Adapter preview does not guarantee exact cross-platform runtime equivalence.</div></div>`)}</div><div>${card(`${target} · ${escapeHtml(getPipeline(state).name)}`, `<pre class="mono-block" style="min-height:280px">${escapeHtml(preview)}</pre>`, { action: button("Copy preview", "copy-artifact", "ghost") })}<div class="toolbar" style="margin-top:9px">${badge(`Logical pipeline · ${tasks.length} tasks`, "blue")}${badge(`${edges.length} dependencies`, "green")}${button("View orchestration", "navigate-orchestration", "ghost")}</div></div></div></div>`;
}

function renderExecution(state) {
  const ops=state.operations;
  const runs=ops.filter(op=>op.type==="Pipeline run"||op.type==="Notebook run");
  const visible=runs.filter(op=>state.executionFilter==="All"||state.executionFilter==="Successful"&&op.state==="Completed"||state.executionFilter==="Failed"&&op.state==="Failed"||state.executionFilter==="Running"&&!['Completed','Failed','Cancelled'].includes(op.state));
  const selected=visible.find(op=>op.id===state.selectedOperation)||visible[0];
  const filterNames=["All","Successful","Failed","Running"];
  return `<div class="page">${pageHead("Execution & Validation", "Inspect simulated runs, phase timelines, metrics and failure evidence.", `${button("Run pipeline", "run-pipeline", "primary")}${button("Refresh", "refresh-operations")}`, "BUILD / EXECUTION CONSOLE")}<div class="split-layout" style="grid-template-columns:265px minmax(0,1fr)"><div>${card("Executions", `<div class="compact-list">${visible.map(op=>`<button class="explorer-link ${op.id===state.selectedOperation?"active":""}" data-action="open-operation" data-id="${op.id}"><span class="link-icon">${op.state==="Failed"?"!":"◷"}</span><span style="overflow:hidden;text-overflow:ellipsis">${escapeHtml(op.target)}</span>${badge(op.state,op.state==="Failed"?"red":op.state==="Completed"?"green":"amber")}</button>`).join("")||`<div class="empty-state compact"><strong>No matching runs</strong><p>Choose another run filter.</p></div>`}</div>`, { action: badge(`${visible.length} runs`) })}${card("Run filters", `<div class="pill-row">${filterNames.map(item=>`<button class="segment ${item===state.executionFilter?"active":""}" data-action="filter-executions" data-value="${item}">${item}</button>`).join("")}</div>`)}</div><div>${selected?card(`Run detail · ${escapeHtml(selected.target)}`, `<div class="toolbar">${badge(selected.state,selected.state==="Failed"?"red":selected.state==="Completed"?"green":"amber")}${badge(selected.started,"blue")}${badge(getWorkspace(state).name)}</div><div class="card-grid four" style="margin-top:10px">${stat("Progress", `${selected.progress}%`, selected.phase||"Current phase", "operate")}${stat("Rows", selected.rows||"2,842", "Reported by simulation", "table")}${stat("Duration", selected.state==="Failed"?"14 sec":"In progress", selected.started, "operate")}${stat("Retries", "0", `Policy allows ${state.orchestration.retries}`, "refresh")}</div><div class="split-layout" style="margin-top:12px"><div><h2 class="canvas-title">Execution timeline</h2><div class="timeline">${(selected.logs||[]).map((log,index)=>`<div class="timeline-item ${selected.state==="Failed"&&/ERROR|failed/i.test(log)?"failed":index<selected.logs.length-1?"done":""}"><strong>${escapeHtml(log.split(" ").slice(2).join(" ")||selected.phase)}</strong><small>${escapeHtml(log.slice(0,8))} · ${escapeHtml(selected.phase||selected.state)}</small></div>`).join("")}</div></div><div><h2 class="canvas-title">Logs</h2><pre class="mono-block">${(selected.logs||[]).map(escapeHtml).join("\n")}</pre>${selected.error?`<div class="notice error" style="margin-top:8px"><span>!</span><div><strong>Actionable failure</strong>${escapeHtml(selected.error)}</div></div>`:`<div class="notice info" style="margin-top:8px"><span>ⓘ</span><div><strong>Simulation evidence</strong>Run metrics and logs are deterministic local demo output.</div></div>`}</div></div>`, { action: button("Ask Dexter to diagnose", "ask-diagnose", "ghost") }):`<div class="empty-state"><strong>No execution to inspect</strong><p>Run a pipeline to create simulated evidence.</p></div>`}</div></div></div>`;
}

function renderTestCenter(state) {
  const categories=["Unit","Integration","Schema","Contract","Data Quality","Referential Integrity","Regression","Runtime Compatibility","Performance"];
  const passed=state.tests.filter(t=>t.state==="Passed").length;
  return `<div class="page">${pageHead("Test & Certification", "Run reusable engineering checks and attach their evidence to delivery readiness.", `${button("Configure suite", "configure-tests")}${button("Run selected tests", "run-tests", "primary")}`, "BUILD / QUALITY GATES")}<div class="card-grid four">${stat("Tests passed", `${passed} / ${state.tests.length}`, "Last run · 09:04", "govern")}${stat("Failed", state.tests.filter(t=>t.state==="Failed").length, "Schema compatibility", "govern")}${stat("Warnings", state.tests.filter(t=>t.state==="Warning").length, "Runtime adapter", "govern")}${stat("Review readiness", state.testReadiness?"Ready":"Blocked", state.testReadiness?"Evidence complete":"Resolve required checks", "deliver")}</div><div class="split-layout" style="margin-top:10px"><div>${card("Test suite", table(["Run", "Test", "Category", "Result", "Duration"], state.tests.map((test,i)=>`<tr><td><input type="checkbox" data-test-select="${i}" ${test.selected!==false?"checked":""}></td><td>${escapeHtml(test.name)}</td><td>${escapeHtml(test.category)}</td><td>${badge(test.state,test.state==="Passed"?"green":test.state==="Failed"?"red":"amber")}${test.detail?`<div class="tiny">${escapeHtml(test.detail)}</div>`:""}</td><td class="mono">${escapeHtml(test.duration)}</td></tr>`)))}</div><div>${card("Scenario coverage", categories.map((category,i)=>`<div class="settings-row"><div><strong>${category}</strong><small>${i%3===0?"2 scenarios":"1 scenario"}</small></div>${badge(i<5?"Included":"Available",i<5?"green":"blue")}</div>`).join(""))}${card("Simulated test scenarios", `<div class="pill-row">${["Empty source","Null fields","Skew","Duplicates","Schema drift","Incremental ingest","Retry","Resume checkpoint","Source failure","Reconciliation"].map(s=>`<label class="pill-select"><input type="checkbox" ${["Null fields","Schema drift","Resume checkpoint"].includes(s)?"checked":""}>${s}</label>`).join("")}</div>`)}</div></div></div>`;
}

function renderProductCatalog(state) {
  const domains=[...new Set(state.products.map(p=>p.domain))];
  const products=state.products.filter(p=>(!state.productSearch||`${p.name} ${p.description} ${p.owner} ${p.domain}`.toLowerCase().includes(state.productSearch.toLowerCase()))&&(state.productDomain==="All"||p.domain===state.productDomain)&&(state.productStatus==="All lifecycle states"||p.status===state.productStatus));
  return `<div class="page">${pageHead("Data Products", "Governed, reusable data resources connect assets, contracts, quality and consumers.", button(`${icon("plus",12)} Create product`, "create-product", "primary"), "DATA PRODUCTS / CATALOG")}<div class="screen-filter"><input class="search-input" placeholder="Search products…" data-filter="products" value="${escapeHtml(state.productSearch)}"><select class="search-input" data-product-domain><option ${state.productDomain==="All"?"selected":""}>All</option>${domains.map(d=>`<option ${state.productDomain===d?"selected":""}>${escapeHtml(d)}</option>`).join("")}</select><select class="search-input" data-product-status><option ${state.productStatus==="All lifecycle states"?"selected":""}>All lifecycle states</option>${["Draft","In Review","Published","Deprecated"].map(s=>`<option ${state.productStatus===s?"selected":""}>${s}</option>`)}</select></div>${[...new Set(products.map(p=>p.domain))].map(domain=>`<div class="section-heading"><h2>${escapeHtml(domain)}</h2><span class="tiny">${products.filter(p=>p.domain===domain).length} products</span></div><div class="card-grid">${products.filter(p=>p.domain===domain).map(product=>`<article class="workspace-card"><div class="toolbar">${badge(product.domain,"blue")}${badge(product.status,product.status==="Published"?"green":"amber")}</div><h3>${escapeHtml(product.name)}</h3><p>${escapeHtml(product.description)}</p><div class="workspace-meta"><span>▦ ${product.assets.length} assets</span><span>⌁ ${product.pipelines.length} pipeline</span><span>◈ ${product.contracts.length} contract</span></div><div class="settings-row"><div><strong>Owner</strong><small>${escapeHtml(product.owner)}</small></div><div><strong>SLO</strong><small>${escapeHtml(product.slo)}</small></div></div><div class="card-foot"><span>${badge(product.quality,product.quality.toLowerCase().includes("warning")?"amber":"green")}</span><button class="button secondary" data-action="open-product" data-id="${product.id}">Open product →</button></div></article>`).join("")}</div>`).join("")||`<div class="empty-state"><strong>No products match</strong><p>Change the search or business domain filter.</p></div>`}</div>`;
}

function renderProductBuilder(state) {
  const draft=state.productDraft; const product=getProduct(state);
  return `<div class="page">${pageHead(product.name || "New Data Product", "Compose a governed product from existing datasets, pipelines and contracts.", `${button("Validate readiness", "validate-product")}${button("Save draft", "save-product", "primary")}`, "DATA PRODUCTS / BUILDER")}<div class="split-layout"><div>${card("Product identity", `<div class="form-stack">${field("Product name", "productDraft.name", draft.name || product.name)}<div class="field"><label>Business purpose</label><textarea data-model="productDraft.purpose" placeholder="Describe the consumer need and data product outcome…">${escapeHtml(draft.purpose || product.description)}</textarea></div><div class="form-grid">${selectField("Domain", "productDraft.domain", draft.domain || product.domain, ["Customer","Sales","Finance","Risk","Operations"])}${field("Owner", "productDraft.owner", draft.owner || product.owner)}</div></div>`, { action: badge(product.status, "amber") })}${card("Output and service level", `<div class="form-grid">${field("Output port", "productDraft.port", draft.port || product.ports[0])}${field("Freshness SLO", "productDraft.slo", draft.slo || product.slo)}${selectField("Lifecycle", "product.lifecycle", product.status, ["Draft","In Review","Published","Deprecated"])}</div><div class="section-heading"><h2>Consumers</h2>${button("+ Add consumer", "add-consumer", "ghost")}</div><div class="pill-row">${[...(product.consumers||[]),...(draft.consumer?[draft.consumer]:[])].map(c=>badge(c,"blue")).join("")}</div>`)}</div><div>${card("Compose product assets", `<h3 class="canvas-title">Datasets</h3><div class="pill-row">${state.assets.filter(a=>a.type==="Table"||a.type==="Dataset").map(asset=>`<label class="pill-select"><input type="checkbox" data-product-asset="${asset.id}" ${draft.selectedAssets.includes(asset.id)?"checked":""}>${escapeHtml(asset.name)}</label>`).join("")}</div><h3 class="canvas-title" style="margin-top:13px">Pipelines</h3><div class="pill-row">${state.pipelines.map(p=>`<label class="pill-select"><input type="checkbox" data-product-pipeline="${p.id}" ${draft.selectedPipelines.includes(p.id)?"checked":""}>${escapeHtml(p.name)}</label>`).join("")}</div><h3 class="canvas-title" style="margin-top:13px">Contracts</h3><div class="pill-row"><label class="pill-select"><input type="checkbox" data-product-contract="customer-profile-v3" ${(draft.selectedContracts||[]).includes("customer-profile-v3")?"checked":""}>customer-profile-v3</label><label class="pill-select"><input type="checkbox" data-product-contract="transaction-fact-v2" ${(draft.selectedContracts||[]).includes("transaction-fact-v2")?"checked":""}>transaction-fact-v2</label></div>`, { action: badge(`${draft.selectedAssets.length} linked assets`, "blue") })}${card("Dependency view", `<div class="lab-topology" style="min-height:170px"><button class="service-node"><strong>${escapeHtml(draft.selectedAssets.map(id=>state.assets.find(a=>a.id===id)?.name).filter(Boolean).join(", ") || product.assets.map(id=>state.assets.find(a=>a.id)?.name).join(", "))}</strong><small>Output datasets</small></button><button class="service-node"><strong>${escapeHtml(draft.selectedPipelines[0] || product.pipelines[0] || "No pipeline")}</strong><small>Producer pipeline</small></button><button class="service-node"><strong>${escapeHtml(draft.port || product.ports[0])}</strong><small>Published output port</small></button></div><div class="notice ${state.testReadiness?"success":""}" style="margin-top:8px"><span>${state.testReadiness?"✓":"!"}</span><div><strong>${state.testReadiness?"Ready to publish":"Draft needs review"}</strong>${state.testReadiness?"Required tests pass and linked contract is valid.":"Resolve the schema compatibility check before requesting publication."}</div></div>`, { action: button("Explore lineage", "navigate-lineage", "ghost") })}</div></div></div>`;
}

function renderOperations(state) {
  const groups=["Active","Queued","Completed","Failed","Cancelled"];
  const filter=state.operationFilter||"All";
  const operations=state.operations.filter(op=>filter==="All"||(filter==="Active"?!['Completed','Failed','Cancelled','Queued'].includes(op.state):op.state===filter));
  return `<div class="page">${pageHead("Operations Center", "Track Lab lifecycle, data movement, pipelines, notebooks, tests and delivery activities.", `${button("Cancel selected", "cancel-selected-operation")}${button("Refresh", "refresh-operations")}`, "OPERATE / ACTIVITY")}<div class="card-grid four">${stat("Active", state.operations.filter(o=>!['Completed','Failed','Cancelled'].includes(o.state)).length, "Across all workspaces", "operate")}${stat("Queued", state.operations.filter(o=>o.state==="Queued").length, "Waiting for resources", "operate")}${stat("Failed", state.operations.filter(o=>o.state==="Failed").length, "Review required", "govern")}${stat("Completed today", state.operations.filter(o=>o.state==="Completed").length, "Successful simulations", "govern")}</div><div class="screen-filter" style="margin:10px 0"><button class="segment ${filter==="All"?"active":""}" data-action="filter-operations" data-value="All">All</button>${groups.map(g=>`<button class="segment ${filter===g?"active":""}" data-action="filter-operations" data-value="${g}">${g} <span class="tiny">${state.operations.filter(o=>g==="Active"?!['Completed','Failed','Cancelled','Queued'].includes(o.state):o.state===g).length}</span></button>`).join("")}</div><div class="panel-card"><div class="panel-card-head"><h2>Recent operations</h2><span class="tiny">Simulated activity · local demo time</span></div><div class="compact-list">${operations.map(op=>`<div class="compact-row"><span class="row-icon ${op.state==="Failed"?"":op.state==="Completed"?"green":"amber"}">${op.type==="Materialization"?"↓":op.type==="Pipeline run"?"⌁":"◷"}</span><div class="row-main"><strong>${escapeHtml(op.target)}</strong><small>${escapeHtml(op.type)} · ${escapeHtml(op.started)} · ${escapeHtml(op.phase || op.state)} ${op.rows?`· ${escapeHtml(op.rows)}`:""}</small>${op.progress<100?`<div class="progress-track ${op.state==="Failed"?"error":""}" style="margin-top:6px"><span style="width:${op.progress}%"></span></div>`:""}${op.error?`<small style="color:var(--red)">${escapeHtml(op.error)}</small>`:""}</div>${badge(`${op.progress}% · ${op.state}`,op.state==="Failed"?"red":op.state==="Completed"?"green":"amber")}${op.state==="Failed"?button(op.id.includes("pipe")?"Retry":"Resume","retry-operation","ghost",`data-id="${op.id}"`):button("Cancel","cancel-operation","ghost",`data-id="${op.id}"`)}${button("Logs","open-operation","ghost",`data-id="${op.id}"`)}</div>`).join("")||`<div class="empty-state compact"><strong>No matching operations</strong><p>Choose another state filter.</p></div>`}</div></div></div>`;
}

function renderLineage(state) {
  const asset=getAsset(state);const source=asset.sourceAssetId?state.assets.find(item=>item.id===asset.sourceAssetId):null;
  const products=state.products.filter(product=>product.assets.includes(asset.id));const workspace=getWorkspace(state);
  const pipelineIds=[...new Set([...products.flatMap(product=>product.pipelines),...workspace.pipelineIds])];
  const pipelines=pipelineIds.map(id=>state.pipelines.find(pipeline=>pipeline.id===id)).filter(Boolean);
  const nodes=[{label:source?.fullName||`${asset.environment} source`,kind:source?"Materialized from":"Source"},{label:asset.fullName,kind:asset.type},{label:pipelines[0]?.name||"No linked pipeline",kind:"Pipeline"},...(products.length?products.map(product=>({label:product.name,kind:"Data Product"})): [{label:"No linked Data Product",kind:"Product"}]),{label:products.flatMap(product=>product.consumers||[]).join(", ")||"Workspace consumers",kind:"Consumer"}];
  const linked=products.reduce((sum,product)=>sum+product.assets.length+product.pipelines.length+product.contracts.length,0)+pipelines.length+1;
  return `<div class="page">${pageHead("Lineage & Dependencies", "Trace upstream sources, transformations, products and consumers. Select a node for impact analysis.", `${button("Upstream", "lineage-upstream")}${button("Downstream", "lineage-downstream", "primary")}`, "OPERATE / LINEAGE")}<div class="toolbar" style="margin-bottom:10px">${selectField("Focus asset", "lineage-asset", asset.id, state.assets.map(a=>a.id))}<div class="segmented"><button class="segment ${state.lineageDepth==="1"||!state.lineageDepth?"active":""}" data-action="lineage-depth" data-value="1">1 hop</button><button class="segment ${state.lineageDepth==="2"?"active":""}" data-action="lineage-depth" data-value="2">2 hops</button><button class="segment ${state.lineageDepth==="all"?"active":""}" data-action="lineage-depth" data-value="all">All</button></div>${badge(`${linked} related objects`, "blue")}</div><div class="lab-topology" style="min-height:280px;justify-content:space-around">${nodes.map((node,i)=>`<button class="service-node ${state.lineageSelected===i?"selected":""}" data-action="lineage-node" data-index="${i}"><span class="eyebrow">${escapeHtml(node.kind)}</span><strong>${escapeHtml(node.label)}</strong><small>${i===0?"Upstream source":i===nodes.length-1?"Downstream consumers":i===nodes.length-2?"Linked product":"Workspace relationship"}</small><span class="node-health">${i===1&&asset.local?"Local copy available":"Relationship in shared demo state"}</span></button>`).join("")}</div><div class="split-layout" style="margin-top:10px">${card("Impact analysis", `<div class="notice info"><span>ⓘ</span><div><strong>Changing ${escapeHtml(asset.fullName)}</strong>${pipelines.length} linked pipelines and ${products.length} linked Data Products may be affected.</div></div>${pipelines.map(pipeline=>`<div class="compact-row"><span class="row-icon">⌁</span><div class="row-main"><strong>${escapeHtml(pipeline.name)}</strong><small>Logical pipeline · ${pipeline.nodes.length} nodes</small></div>${screenButton("Open pipeline", "pipeline-studio", "ghost", `data-id="${pipeline.id}"`)}</div>`).join("")}${products.map(product=>`<div class="compact-row"><span class="row-icon">◈</span><div class="row-main"><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.ports.join(", ")||"No output port")}</small></div><button class="button ghost" data-action="open-product" data-id="${product.id}">Open product</button></div>`).join("")||`<p class="tiny">No current product links this asset.</p>`}`, { action: badge("Shared relationships", "blue") })}${card("Relationships", table(["Direction", "Object", "Type"],nodes.map((node,i)=>`<tr><td>${i===0?"Upstream":i===1?"Focus":"Downstream"}</td><td>${escapeHtml(node.label)}</td><td>${escapeHtml(node.kind)}</td></tr>`)))}</div></div>`;
}

function renderContracts(state) {
  const asset=getAsset(state);
  const tabs=[["contract","Contract"],["quality","Quality rules"],["evidence","Test evidence"]];
  const content=state.contractTab==="quality"
    ? table(["Rule","Expectation","Latest result","Evidence"],[`<tr><td>Primary key uniqueness</td><td>${escapeHtml(asset.schema[0]?.[0]||"id")} is unique</td><td>${badge("Passed","green")}</td><td>0 duplicate keys</td></tr>`,`<tr><td>Required fields</td><td>Non-null contract columns</td><td>${badge(state.sourceSchemaFixed?"Passed":"Failed",state.sourceSchemaFixed?"green":"red")}</td><td>${state.sourceSchemaFixed?"All required columns found":"customer_tier missing"}</td></tr>`,`<tr><td>Freshness</td><td>Updated within 24 hours</td><td>${badge("Passed","green")}</td><td>${escapeHtml(asset.updated)}</td></tr>`])
    : state.contractTab==="evidence"
      ? table(["Test","Category","Result","Duration"],state.tests.map(test=>`<tr><td>${escapeHtml(test.name)}</td><td>${escapeHtml(test.category)}</td><td>${badge(test.state,test.state==="Passed"?"green":test.state==="Failed"?"red":"amber")}</td><td>${escapeHtml(test.duration)}</td></tr>`))
      : table(["Field","Expected type","Requirement","Quality rule"],asset.schema.map(([name,type,nullable],i)=>`<tr><td class="mono">${escapeHtml(name)}</td><td><select class="input mono" data-contract-field="${i}" data-key="type"><option>${escapeHtml(type)}</option><option>STRING</option><option>INTEGER</option><option>DATE</option></select></td><td><select class="input" data-contract-field="${i}" data-key="nullable"><option>${escapeHtml(nullable)}</option><option>Required</option><option>Optional</option></select></td><td>${i===0?"Unique + not null":i===1?"Email format when present":i===3?"Allowed values: Gold, Silver, Bronze":"Type compatibility"}</td></tr>`));
  return `<div class="page">${pageHead("Contracts & Data Quality", "Versioned expectations connect schemas, assets and test evidence.", `${button("New contract draft", "new-contract")}${button("Run quality checks", "run-tests", "primary")}`, "GOVERN / CONTRACTS")}<div class="screen-filter"><select class="search-input" data-model="contract-asset">${assetOptions(state).replace(`value="${asset.id}"`,`value="${asset.id}" selected`)}</select><div class="segmented">${tabs.map(([id,label])=>`<button class="segment ${state.contractTab===id?"active":""}" data-action="contract-tab" data-value="${id}">${label}</button>`).join("")}</div></div><div class="split-layout" style="margin-top:10px"><div>${card(`${escapeHtml(asset.name)} · ${state.contractTab==="evidence"?"Test evidence":state.contractTab==="quality"?"Quality rules":"Contract v3"}`,content)}${state.contractTab==="contract"?`<div class="toolbar" style="margin-top:9px">${button("Add field", "add-contract-field")}${button("Save draft", "save-contract", "primary")}${badge("v3 · Draft", "amber")}</div>`:""}</div><div>${card("Validation status", `<div class="settings-row"><div><strong>Required fields</strong><small>${state.sourceSchemaFixed?"6 of 6":"5 of 6 present"}</small></div>${badge(state.sourceSchemaFixed?"Passed":"Failed",state.sourceSchemaFixed?"green":"red")}</div><div class="settings-row"><div><strong>Schema compatibility</strong><small>Source schema v2 → contract v3</small></div>${badge(state.sourceSchemaFixed?"Compatible":"Mismatch",state.sourceSchemaFixed?"green":"amber")}</div><div class="settings-row"><div><strong>PII handling</strong><small>email masked in synthetic data</small></div>${badge("Reviewed", "green")}</div>${state.sourceSchemaFixed?`<div class="notice success" style="margin-top:9px"><span>✓</span><div><strong>Schema aligned</strong>Required fields are available in the source schema.</div></div>`:`<div class="notice error" style="margin-top:9px"><span>!</span><div><strong>customer_tier missing</strong>The source schema does not satisfy this required contract field.</div></div>`}`,{action:button("Open test evidence","navigate-test-center","ghost")})}${card("Associated assets", `<div class="compact-row"><span class="row-icon">▦</span><div class="row-main"><strong>${escapeHtml(asset.fullName)}</strong><small>${asset.environment} · ${asset.classification}</small></div>${screenButton("Open", "table-workbench", "ghost")}</div>`)}</div></div></div>`;
}
function renderProfiling(state) {
  const asset=getAsset(state); const bars=[72,43,88,26,63,97,54,78,34,60,92,49,71,39,84,58];
  return `<div class="page">${pageHead("Data Profiling", `${asset.fullName} · distribution and quality signals from representative demo data.`, `${button("Refresh profile", "refresh-profile")}${button("Suggest quality rules", "suggest-quality-rules", "primary")}`, "GOVERN / DATA PROFILE")}<div class="screen-filter"><select class="search-input" data-model="profile-asset">${assetOptions(state).replace(`value="${asset.id}"`,`value="${asset.id}" selected`)}</select><span class="badge blue">Profile generated 12 min ago</span></div><div class="card-grid four" style="margin-top:10px">${stat("Rows",Number(asset.rows).toLocaleString(),"Estimated source count","table")}${stat("Columns",asset.schema.length,"1 key · 4 nullable","table")}${stat("Volume",asset.size,"Current source snapshot","database")}${stat("Quality score","98.2%","3 rules · 1 warning","govern")}</div><div class="split-layout" style="margin-top:10px"><div>${card("Column distributions", `<div class="section-heading"><h2>transaction_date · daily record count</h2><span class="tiny">Last 30 days</span></div><div class="chart-bars">${bars.map((height,i)=>`<div class="chart-bar" style="height:${height}%"><span>${i+1}</span></div>`).join("")}</div><div class="section-heading"><h2>Common values · channel</h2></div><div class="settings-row"><div><strong>web</strong><small>Distinct 3 · 48.2%</small></div><span class="mono">2.27M</span></div><div class="settings-row"><div><strong>store</strong><small>Distinct 3 · 37.4%</small></div><span class="mono">1.76M</span></div><div class="settings-row"><div><strong>partner</strong><small>Distinct 3 · 14.4%</small></div><span class="mono">679K</span></div>`, { action: badge("Representative sample", "blue") })}</div><div>${card("Field statistics", table(["Field", "Null %", "Distinct", "Min / max", "Signal"], asset.schema.map(([name,type],i)=>`<tr><td class="mono">${escapeHtml(name)}</td><td>${[0,3].includes(i)?"0.0%":"1.8%"}</td><td>${i===0?"4.7M":i===3?"3":"182.4K"}</td><td>${type.includes("DATE")?"2025-01-01 … 2026-11-03":type.includes("DECIMAL")?"-4,200 … 81,430":"—"}</td><td>${i===3?badge("Review","amber"):badge("Healthy","green")}</td></tr>`))) }${card("Quality warnings", `<div class="notice"><span>!</span><div><strong>customer_tier null ratio · 1.8%</strong>Within the 2% threshold. Add a quality rule to track change.</div></div><div class="notice info" style="margin-top:7px"><span>ⓘ</span><div><strong>Volume trend +4.2%</strong>Record count is within the expected weekly range.</div></div>`)}</div></div></div>`;
}

function renderRepositories(state) {
  const matches=state.repositories.filter(repo=>(!state.repositorySearch||`${repo.path} ${repo.owner} ${repo.technology}`.toLowerCase().includes(state.repositorySearch.toLowerCase()))&&(state.repositoryProvider==="All providers"||repo.provider===state.repositoryProvider)&&(state.repositoryDomain==="All domains"||repo.domain===state.repositoryDomain));
  return `<div class="page">${pageHead("Repositories", "Browse simulated corporate Git destinations and connect a workspace to its delivery repository.", button("Connect repository", "connect-repository", "primary"), "DELIVER / REPOSITORY EXPLORER")}<div class="screen-filter"><input class="search-input" placeholder="Search repositories…" data-filter="repositories" value="${escapeHtml(state.repositorySearch)}"><select class="search-input" data-repository-provider>${["All providers","GitHub Enterprise","GitLab"].map(provider=>`<option ${state.repositoryProvider===provider?"selected":""}>${provider}</option>`).join("")}</select><select class="search-input" data-repository-domain>${["All domains","Customer","Risk","Finance"].map(domain=>`<option ${state.repositoryDomain===domain?"selected":""}>${domain}</option>`).join("")}</select></div><div class="split-layout" style="margin-top:10px;grid-template-columns:minmax(0,1fr) 250px"><div>${table(["Repository","Provider","Domain","Owner","Technology","Default branch","Access"],matches.map(repo=>`<tr class="selectable ${state.selectedRepository===repo.id?"selected":""}" data-action="select-repository" data-id="${repo.id}"><td><strong>${escapeHtml(repo.path)}</strong><div class="tiny">Updated ${escapeHtml(repo.updated)}</div></td><td>${escapeHtml(repo.provider)}</td><td>${escapeHtml(repo.domain)}</td><td>${escapeHtml(repo.owner)}</td><td>${escapeHtml(repo.technology)}</td><td class="mono">${escapeHtml(repo.branch)}</td><td>${repo.access==="Restricted"?badge("Restricted","red"):badge("Write access","green")}</td></tr>`))}</div>${card("Repository details", `<span class="eyebrow">SELECTED REPOSITORY</span><h2 style="font-size:13px">${escapeHtml(getRepository(state).path)}</h2><p class="tiny">${escapeHtml(getRepository(state).provider)} · ${escapeHtml(getRepository(state).technology)}</p><div class="settings-row"><div><strong>Default branch</strong><small>${escapeHtml(getRepository(state).branch)}</small></div></div><div class="settings-row"><div><strong>Access</strong><small>${getRepository(state).access==="Restricted"?"Request owner approval":"Simulated write permission"}</small></div>${badge(getRepository(state).access,getRepository(state).access==="Restricted"?"red":"green")}</div><div class="toolbar" style="margin-top:8px">${button("Associate to workspace", "associate-repository", "primary", getRepository(state).access==="Restricted"?"disabled":"")}${button("Browse branches", "browse-branches")}</div>`, { action: badge("Mock Git provider", "blue") })}</div></div>`;
}
function renderArtifactReview(state) {
  const repo=getRepository(state); const selected=state.selectedFiles||[];
  return `<div class="page">${pageHead("Artifact Review", `Review generated changes for ${repo.path} before opening a simulated Pull Request.`, `${button("Run validation", "run-tests")}${button("Ready for Review", "navigate-pr-wizard", "primary")}`, "DELIVER / CHANGES")}<div class="split-layout" style="grid-template-columns:250px minmax(0,1fr)"><div>${card("Generated files", `<div class="settings-row"><div><strong>${escapeHtml(repo.path)}</strong><small>Branch · ${escapeHtml(getWorkspace(state).branch)}</small></div>${badge("3 changed", "amber")}</div>${repo.files.map((file,i)=>`<label class="file-row ${selected.includes(file)?"selected":""}"><input type="checkbox" data-file-select="${escapeHtml(file)}" ${selected.includes(file)?"checked":""}><span>${i===0?"MD":file.endsWith(".py")?"PY":file.endsWith(".yaml")?"YM":file.endsWith(".ipynb")?"NB":"TS"}</span>${escapeHtml(file)}<span class="file-size">${i===0?"1.2 KB":"2.8 KB"}</span></label>`).join("")}`)}${card("Validation evidence", `<div class="settings-row"><div><strong>Tests</strong><small>${state.testReadiness?"All required checks passed":"Schema check needs attention"}</small></div>${badge(state.testReadiness?"Passed":"Review",state.testReadiness?"green":"amber")}</div><div class="settings-row"><div><strong>Adapter warnings</strong><small>Airflow mapping reviewed</small></div>${badge("1 warning","amber")}</div>`)}</div><div>${card(`Diff · ${selected[0]||"pipelines/customer_ingest.py"}`, `<div class="toolbar" style="margin-bottom:7px"><div class="segmented"><button class="segment active" data-action="diff-mode" data-value="split">Split</button><button class="segment" data-action="diff-mode" data-value="unified">Unified</button></div>${badge("+18 additions", "green")}${badge("−4 removals", "red")}</div><div class="diff-view"><div class="diff-pane"><div class="diff-head">Base · ${escapeHtml(repo.branch)}</div><div class="diff-line"><span class="line-no">11</span>def load_customers():</div><div class="diff-line removed"><span class="line-no">12 −</span>    return spark.read.table("customer.raw")</div><div class="diff-line"><span class="line-no">13</span>    validate_schema(source)</div><div class="diff-line"><span class="line-no">14</span>    return source</div></div><div class="diff-pane"><div class="diff-head">Changes · feature/customer-incremental-load</div><div class="diff-line"><span class="line-no">11</span>def load_customers(checkpoint):</div><div class="diff-line added"><span class="line-no">12 +</span>    source = read_incremental(checkpoint)</div><div class="diff-line added"><span class="line-no">13 +</span>    assert_required_fields(source, profile_v3)</div><div class="diff-line"><span class="line-no">14</span>    return source</div></div></div><div class="section-heading"><h2>Change summary</h2></div><p class="tiny">Adds an incremental customer source, validates profile contract v3 and covers checkpoint replay in tests.</p>`, { action: button("Open file", "open-selected-file", "ghost") })}</div></div></div>`;
}

function renderPrWizard(state) {
  const stages=["Repository","Branch","Artifacts","Tests","Details","Review","Create"];
  return `<div class="page">${pageHead("Ready for Review", "Prepare a simulated Pull Request. Creating a PR does not deploy or merge code.", "", "DELIVER / PULL REQUEST WIZARD")}<div class="wizard-steps">${stages.map((step,i)=>`<div class="wizard-step ${state.delivery.stage===i+1?"active":state.delivery.stage>i+1?"done":""}"><span>${state.delivery.stage>i+1?"✓":i+1}</span>${step}</div>`).join("")}</div><div class="split-layout"><div>${card(`${stages[state.delivery.stage-1]} · Step ${state.delivery.stage} of ${stages.length}`, prStage(state))}<div class="wizard-footer"><button class="button secondary" data-action="pr-back" ${state.delivery.stage===1?"disabled":""}>← Back</button><div class="toolbar"><button class="button ghost" data-action="cancel-pr">Cancel</button><button class="button primary" data-action="pr-next">${state.delivery.stage===7?"Create simulated Pull Request":"Continue →"}</button></div></div></div><div>${card("Delivery summary", `<div class="settings-row"><div><strong>Workspace</strong><small>${escapeHtml(getWorkspace(state).name)}</small></div>${badge("Active")}</div><div class="settings-row"><div><strong>Repository</strong><small>${escapeHtml(getRepository(state).path)}</small></div>${badge(getRepository(state).access,"green")}</div><div class="settings-row"><div><strong>Changed files</strong><small>${state.selectedFiles.length} selected</small></div>${badge("Review")}</div><div class="settings-row"><div><strong>Validation</strong><small>${state.tests.filter(t=>t.state==="Passed").length} passed · ${state.tests.filter(t=>t.state==="Failed").length} failed</small></div>${badge(state.testReadiness?"Ready":"Attention",state.testReadiness?"green":"amber")}</div><div class="notice info" style="margin-top:8px"><span>ⓘ</span><div><strong>No deployment is triggered</strong>This creates a mock PR record in local demo state only.</div></div>`)}</div></div></div>`;
}

function prStage(state) {
  const repo=getRepository(state); const stage=state.delivery.stage;
  if(stage===1) return `<div class="field"><label>Repository</label><select data-model="selectedRepository">${state.repositories.map(r=>`<option value="${r.id}" ${repo.id===r.id?"selected":""}>${escapeHtml(r.path)} · ${r.provider}</option>`).join("")}</select><small>Restricted repositories are visible but cannot be selected for delivery.</small></div><div class="notice ${repo.access==="Restricted"?"error":"info"}" style="margin-top:10px">${repo.access==="Restricted"?"This repository requires simulated access approval.":"Repository operations are simulated; no Git provider will be contacted."}</div>`;
  if(stage===2) return `<div class="field"><label>Target branch</label><select data-model="delivery.branch"><option>main</option><option>develop</option><option>release/2026-q4</option></select></div><div class="field" style="margin-top:10px"><label>Feature branch</label><input data-model="delivery.featureBranch" value="${escapeHtml(getWorkspace(state).branch)}"></div>`;
  if(stage===3) return `<div class="field"><label>Files included in the proposed change</label><div class="panel-card" style="margin-top:5px">${repo.files.map(file=>`<label class="file-row"><input type="checkbox" data-file-select="${escapeHtml(file)}" ${state.selectedFiles.includes(file)?"checked":""}>${escapeHtml(file)}</label>`).join("")}</div></div>`;
  if(stage===4) return `<div class="settings-row"><div><strong>Test evidence</strong><small>${state.tests.filter(t=>t.state==="Passed").length} passed · ${state.tests.filter(t=>t.state==="Failed").length} failed · ${state.tests.filter(t=>t.state==="Warning").length} warning</small></div>${badge(state.testReadiness?"Ready":"Review",state.testReadiness?"green":"amber")}</div><div class="toolbar" style="margin-top:10px">${button("Run selected tests", "run-tests", "secondary")}${screenButton("Review test results", "test-center", "ghost")}</div><p class="tiny">The wizard can create a PR with failing checks, but the readiness state and evidence remain visible.</p>`;
  if(stage===5) return `<div class="form-stack"><div class="field"><label>Pull Request title</label><input data-model="delivery.title" value="${escapeHtml(state.delivery.title)}"></div><div class="field"><label>Description</label><textarea data-model="delivery.description">${escapeHtml(state.delivery.description)}</textarea></div><div class="field"><label>Reviewers</label><input data-model="delivery.reviewers" value="customer-data-reviewers" placeholder="Team or user names"></div></div>`;
  if(stage===6) return `<div class="panel-card"><div class="panel-card-body"><h2 style="font-size:13px">${escapeHtml(state.delivery.title)}</h2><p class="tiny">${escapeHtml(state.delivery.description)}</p><div class="settings-row"><div><strong>${escapeHtml(repo.path)}</strong><small>${escapeHtml(getWorkspace(state).branch)} → main</small></div>${badge("Simulated")}</div><div class="settings-row"><div><strong>${state.selectedFiles.length} generated files</strong><small>Includes pipeline, contract and tests</small></div>${badge("Review")}</div><div class="settings-row"><div><strong>Validation evidence</strong><small>${state.tests.filter(t=>t.state==="Passed").length} passed · ${state.tests.filter(t=>t.state==="Failed").length} failed</small></div>${badge(state.testReadiness?"Ready":"Attention",state.testReadiness?"green":"amber")}</div></div></div>`;
  return `<div class="notice info"><span>ⓘ</span><div><strong>Ready to create a simulated PR</strong>The new item will be added to Delivery Status and workspace history. No Git operation will be performed.</div></div>`;
}

function renderDelivery(state) {
  return `<div class="page">${pageHead("Delivery Status", "Follow Pull Request review, validation checks and delivery history for this workspace.", `${button("Start review workflow", "navigate-pr-wizard", "primary")}${button("Refresh status", "refresh-operations")}`, "DELIVER / STATUS")}<div class="card-grid four">${stat("Open PRs", state.prs.length, "Across connected repositories", "git")}${stat("Checks running", state.prs.filter(pr=>pr.state==="Checks Running").length, "Simulated CI", "operate")}${stat("Ready to merge", state.prs.filter(pr=>pr.state==="Approved").length, "Review evidence required", "govern")}${stat("Deployment", "Not started", "PR review is separate from release", "deliver")}</div>${card("Pull Requests", state.prs.map(pr=>`<div class="compact-row"><span class="row-icon amber">⑂</span><div class="row-main"><strong>#${pr.number} · ${escapeHtml(pr.title)}</strong><small>${escapeHtml(pr.repository)} · ${escapeHtml(pr.branch)} · ${escapeHtml(pr.created)} · ${escapeHtml(pr.workspace)}</small></div>${badge(pr.state,pr.state==="Approved"?"green":pr.state==="Changes Requested"?"red":"amber")}${badge(`${pr.checks} checks`)}${button("Open", "open-pr", "ghost", `data-id="${pr.number}"`)}${button("Update state", "advance-pr", "secondary", `data-id="${pr.number}"`)}</div>`).join("") || `<div class="empty-state"><strong>No Pull Requests yet</strong><p>Use Ready for Review to prepare and create a simulated PR.</p></div>`, { action: badge("Mock repository state", "blue") })}<div class="split-layout" style="margin-top:10px">${card("Validation checks", table(["Check", "Result", "Duration", "Evidence"], state.tests.slice(0,4).map(test=>`<tr><td>${escapeHtml(test.name)}</td><td>${badge(test.state,test.state==="Passed"?"green":test.state==="Failed"?"red":"amber")}</td><td>${escapeHtml(test.duration)}</td><td>${escapeHtml(test.detail||"See test run")}</td></tr>`)))}${card("Delivery history", `<div class="timeline"><div class="timeline-item done"><strong>Artifacts generated</strong><small>Today, 08:58 · ${state.selectedFiles.length} files</small></div><div class="timeline-item done"><strong>Review prepared</strong><small>Today, 09:04 · Customer Ingestion</small></div><div class="timeline-item"><strong>Pull Request opened</strong><small>${state.prs.length?escapeHtml(state.prs[0].created):"Pending"}</small></div></div>`)}</div></div>`;
}

function renderSettings(state) {
  return `<div class="page">${pageHead("Platform & Workspace Settings", "Configure local workspace preferences and inspect simulated service connections.", `${button("Reset demo", "confirm-reset", "danger")}${button("Save settings", "save-settings", "primary")}`, "PLATFORM / SETTINGS")}<div class="split-layout"><div>${card("Workspace defaults", `<div class="settings-row"><div><strong>Active workspace</strong><small>Project context used for new assets</small></div><select data-model="activeWorkspace">${state.workspaces.map(w=>`<option value="${w.id}" ${w.id===state.activeWorkspace?"selected":""}>${escapeHtml(w.name)}</option>`).join("")}</select></div><div class="settings-row"><div><strong>Default data environment</strong><small>Asset-specific environments remain independent</small></div><select data-model="environment"><option ${state.environment==="LOCAL"?"selected":""}>LOCAL</option><option ${state.environment==="DEV"?"selected":""}>DEV</option><option ${state.environment==="PROD"?"selected":""}>PROD</option></select></div><div class="settings-row"><div><strong>Default runtime</strong><small>For new SQL and notebooks</small></div><select data-model="settings.runtime"><option>DuckDB Local</option><option>Python Local</option><option>PySpark Local</option><option>Databricks Connected — Mock</option></select></div><div class="settings-row"><div><strong>Theme</strong><small>Prototype appearance</small></div><select data-model="theme"><option>Dark</option><option>System</option><option>Light (demo)</option></select></div>`)}</div><div>${card("Local resources", `<div class="settings-row"><div><strong>Workspace storage</strong><small>Local datasets retained in demo state</small></div>${badge("1.82 GB of 50 GB","green")}</div><div class="settings-row"><div><strong>Previous snapshots</strong><small>Max one previous snapshot · default 24h TTL</small></div>${badge("Enabled","blue")}</div><div class="settings-row"><div><strong>Auto-save editor tabs</strong><small>Stored in browser localStorage</small></div><button class="switch on" data-action="toggle-switch" aria-label="Toggle auto-save"></button></div><div class="settings-row"><div><strong>Reset on next visit</strong><small>Keep demo state across refresh</small></div><button class="switch" data-action="toggle-switch" aria-label="Toggle reset on next visit"></button></div>`)}</div></div><div class="split-layout" style="margin-top:10px">${card("Connected services", `<div class="settings-row"><div><strong>Databricks workspace</strong><small>analytics-demo.azuredatabricks.net · simulated</small></div>${badge("Demo", "amber")}</div><div class="settings-row"><div><strong>GitHub Enterprise</strong><small>git.corp.example · simulated</small></div>${badge("Mock provider", "blue")}</div><div class="settings-row"><div><strong>Model provider</strong><small>Ask Dexter scripted responses · no LLM configured</small></div>${badge("Offline mock", "green")}</div>`, { action: button("Configure connections", "configure-connections", "ghost") })}${card("Assistant preferences", `<div class="settings-row"><div><strong>Ask Dexter history</strong><small>${state.chat.length} visible messages · persists in this browser</small></div>${button("Clear conversation", "clear-chat", "danger")}</div><div class="settings-row"><div><strong>Context policy</strong><small>Context attaches only when explicitly selected</small></div>${badge("Explicit", "green")}</div><div class="settings-row"><div><strong>Response style</strong><small>Concise engineering guidance</small></div><select><option>Concise</option><option>Detailed</option></select></div>`)}</div></div></div>`;
}

export function renderScreen(state) {
  const renderers = {
    home: renderHome, workspaces: renderWorkspaces, "workspace-overview": renderWorkspaceOverview,
    discover: renderDiscover, "table-workbench": renderTableWorkbench, "table-compare": renderCompare,
    "synthetic-studio": renderSynthetic, "local-data": renderLocalData, "movement-wizard": renderMovement,
    "lab-gallery": renderLabGallery, "lab-composer": renderLabComposer, "schema-designer": renderSchemaDesigner,
    "mock-behavior": renderMockBehavior, "lab-resources": renderLabResources, "lab-cockpit": renderLabCockpit,
    "notebook-studio": renderNotebook, "sql-workspace": renderSql, "pipeline-studio": renderPipeline,
    orchestration: renderOrchestration, "artifact-preview": renderArtifactPreview, "execution-console": renderExecution,
    "test-center": renderTestCenter, "product-catalog": renderProductCatalog, "product-builder": renderProductBuilder,
    operations: renderOperations, lineage: renderLineage, contracts: renderContracts, profiling: renderProfiling,
    repositories: renderRepositories, "artifact-review": renderArtifactReview, "pr-wizard": renderPrWizard,
    "delivery-status": renderDelivery, settings: renderSettings
  };
  return (renderers[state.screen] || renderHome)(state);
}

export function renderWorkspaceToolbar(state) {
  const info=screenInfo(state.screen);
  const actionMap={discover:["Refresh catalog", "refresh-catalog"], "table-workbench":["Open in SQL", "open-sql"], "sql-workspace":["Run query", "run-sql"], "pipeline-studio":["Run pipeline", "run-pipeline"], "notebook-studio":["Run all", "run-notebook"], operations:["Refresh operations", "refresh-operations"], "lab-cockpit":["Start or stop Lab", "lab-start"], "artifact-review":["Ready for Review", "navigate-pr-wizard"]};
  const action=actionMap[state.screen];
  return `<div class="view-heading"><h1>${icon(info.module==="Discover"?"discover":info.module==="Build"?"build":info.module==="Deliver"?"deliver":"workspace",15)} ${escapeHtml(info.title)}</h1><p>${escapeHtml(getWorkspace(state).name)} <span class="muted">· ${escapeHtml(state.activeTabEnvironment||state.environment)} tab · ${escapeHtml(state.environment)} default</span></p></div><div class="toolbar-actions">${state.screen==="home"?`<span class="badge green">LOCAL workspace</span>`:""}${action ? button(action[0], action[1], state.screen==="sql-workspace"||state.screen==="pipeline-studio"?"primary":"ghost") : ""}<button class="icon-button" data-action="toggle-explorer" aria-label="Toggle explorer" title="Toggle explorer">◧</button><button class="icon-button" data-action="toggle-context" aria-label="Toggle context panel" title="Toggle context panel">▣</button></div>`;
}

export function renderExplorer(state) {
  if(state.explorerCollapsed) return `<div class="explorer-collapsed-rail"><button class="icon-button" data-action="toggle-explorer" aria-label="Expand explorer" title="Expand explorer">›</button></div>`;
  const module=modules.find(item=>item.id===state.activeModule) || modules[0];
  const views=module.screens.map(id=>{const item=screenInfo(id);return `<button class="explorer-link ${state.screen===id?"active":""}" data-screen="${id}"><span class="link-icon">${icon(item.module==="Discover"?"table":item.module==="Build"?"build":item.module==="Deliver"?"git":item.module==="Operate"?"operate":"file",12)}</span><span>${escapeHtml(item.title)}</span>${id==="operations"?`<span class="link-count">${state.operations.filter(o=>!['Completed','Failed','Cancelled'].includes(o.state)).length}</span>`:""}</button>`;}).join("");
  let extra="";
  if(state.activeModule==="discover") extra=`<div class="explorer-section"><div class="explorer-section-title">Catalog explorer <span>⌄</span></div>${["PROD","DEV","LOCAL"].map(env=>`<details class="tree-group" ${env==="PROD"?"open":""}><summary class="tree-row"><span class="tree-dot ${env==="LOCAL"?"local":""}"></span>${env}<small>${env==="LOCAL"?`${state.assets.filter(asset=>asset.environment==="LOCAL").length} datasets`:"catalogs"}</small></summary><div class="tree-branch">${state.assets.filter(a=>a.environment===env).map(asset=>`<button class="tree-row ${state.selectedAsset===asset.id?"selected":""}" data-action="select-asset" data-id="${asset.id}"><span class="tree-dot ${asset.local?"local":""}"></span>${escapeHtml(asset.fullName.split(".").slice(-1)[0])}<small>${asset.type==="Table"?"tbl":"obj"}</small></button>`).join("")}</div></details>`).join("")}</div>`;
  else if(state.activeModule==="build") extra=`<div class="explorer-section"><div class="explorer-section-title">Current project</div><button class="explorer-link" data-screen="workspace-overview"><span class="link-icon">⌂</span>${escapeHtml(getWorkspace(state).name)}</button><div class="tree-branch"><button class="tree-row" data-screen="lab-cockpit"><span class="tree-dot local"></span>${escapeHtml(getLab(state).name)}</button>${state.pipelines.map(p=>`<button class="tree-row" data-action="select-pipeline" data-id="${p.id}"><span class="tree-dot"></span>${escapeHtml(p.name)}</button>`).join("")}${state.notebooks.map(n=>`<button class="tree-row" data-action="select-notebook" data-id="${n.id}"><span class="tree-dot view"></span>${escapeHtml(n.name)}</button>`).join("")}</div></div>`;
  else if(state.activeModule==="workspaces") extra=`<div class="explorer-section"><div class="explorer-section-title">Recent workspaces</div>${state.workspaces.map(ws=>`<button class="explorer-link ${state.activeWorkspace===ws.id?"active":""}" data-action="open-workspace" data-id="${ws.id}"><span class="link-icon">⌂</span>${escapeHtml(ws.name)}</button>`).join("")}</div>`;
  else if(state.activeModule==="deliver") extra=`<div class="explorer-section"><div class="explorer-section-title">Repository</div><button class="explorer-link" data-screen="repositories"><span class="link-icon">⑂</span>${escapeHtml(getRepository(state).path)}</button><div class="tree-branch">${getRepository(state).files.map(f=>`<button class="tree-row" data-action="select-file" data-name="${escapeHtml(f)}"><span class="tree-dot view"></span>${escapeHtml(f.split("/").at(-1))}</button>`).join("")}</div></div>`;
  else if(state.activeModule==="products") extra=`<div class="explorer-section"><div class="explorer-section-title">Business domains</div>${["Customer","Sales","Finance","Risk","Operations"].map(d=>`<button class="explorer-link" data-action="filter-product-domain" data-value="${d}"><span class="link-icon">◈</span>${d}<span class="link-count">${state.products.filter(p=>p.domain===d).length||"—"}</span></button>`).join("")}</div>`;
  else if(state.activeModule==="operate"||state.activeModule==="govern") extra=`<div class="explorer-section"><div class="explorer-section-title">Needs attention</div><button class="explorer-link" data-screen="execution-console"><span class="link-icon">!</span>Failed pipeline run<span class="link-count">1</span></button><button class="explorer-link" data-screen="contracts"><span class="link-icon">◈</span>Schema mismatch<span class="link-count">1</span></button></div>`;
  return `<div class="explorer-head"><div><h2>${escapeHtml(module.label)}</h2><p>${module.id==="build"?escapeHtml(getWorkspace(state).name):"Dexter engineering workspace"}</p></div><button class="icon-button" data-action="collapse-explorer" aria-label="Collapse explorer">‹</button></div><div class="explorer-scroll">${module.id!=="home"?`<div class="explorer-search"><span>⌕</span><input placeholder="Filter ${module.label.toLowerCase()}…" data-filter="explorer"></div>`:""}<div class="explorer-section"><div class="explorer-section-title">${module.id==="home"?"Overview":"Experiences"}<span>${module.screens.length}</span></div>${views}</div>${extra}<div class="explorer-section"><div class="explorer-section-title">Quick create</div><button class="explorer-link" data-action="create-quick" data-kind="pipeline"><span class="link-icon">＋</span>New pipeline</button><button class="explorer-link" data-action="create-quick" data-kind="notebook"><span class="link-icon">＋</span>New notebook</button><button class="explorer-link" data-action="create-quick" data-kind="lab"><span class="link-icon">＋</span>New Lab</button></div></div><div class="explorer-footer"><span class="status-dot"></span>Demo workspace state<span style="margin-left:auto">local</span></div>`;
}

export function renderPrimaryNav(state) {
  return `${modules.map(module=>`<button class="rail-item ${state.activeModule===module.id?"active":""}" data-module="${module.id}" data-screen="${module.screens[0]}" aria-label="${module.label}">${icon(module.icon,18)}<span>${module.label}</span><i class="rail-tip">${module.label}</i></button>`).join("")}`;
}

export function renderTabs(state) {
  return `<div class="tab-list">${state.tabs.map(tab=>`<button class="editor-tab ${tab.id===state.screen?"active":""}" role="tab" aria-selected="${tab.id===state.screen}" data-screen="${tab.id}" data-tab-id="${tab.id}"><span class="tab-icon">${icon(screenInfo(tab.id).module==="Build"?"build":screenInfo(tab.id).module==="Discover"?"table":"file",12)}</span><span class="tab-title">${escapeHtml(tab.title)}</span>${tab.dirty?`<span class="tab-dirty">●</span>`:""}${tab.id!=="home"?`<span class="tab-close" data-action="close-tab" data-id="${tab.id}" aria-label="Close ${escapeHtml(tab.title)}">×</span>`:""}</button>`).join("")}</div><button class="tab-add" data-action="open-command-palette" aria-label="Open a workspace">＋</button>`;
}

export function renderContext(state) {
  if(state.contextCollapsed) return `<div class="context-head"><button class="icon-button" data-action="toggle-context" aria-label="Expand contextual panel">✳</button></div>`;
  const contextText = state.chatContext.length ? state.chatContext.map(id=>{const asset=state.assets.find(a=>a.id===id);const product=state.products.find(p=>p.id===id);return asset?asset.fullName:product?product.name:id;}) : [];
  let body="";
  if(state.contextTab==="assistant") body=`<div class="context-scroll"><div class="assistant-title-row"><span class="assistant-mark">✳</span><div><strong>Ask Dexter</strong><small>Context-aware engineering assistant · mock</small></div>${button("Clear", "clear-chat", "ghost")}</div><p class="tiny">Choose exactly what the assistant can use. No real model or data provider is connected.</p><div class="context-pill-row">${contextText.map((name,i)=>`<span class="context-chip">${escapeHtml(name)}<button data-action="remove-chat-context" data-index="${i}" aria-label="Remove context">×</button></span>`).join("")}${button("+ Add current context", "attach-current-context", "ghost")}</div><div class="chat-history">${state.chat.map((message,i)=>`<article class="chat-message ${message.role}">${message.role==="assistant"?`<span class="mini-assistant">✳</span>`:""}<div><p>${escapeHtml(message.text)}</p>${message.proposal?`<div class="proposal-card"><strong>Proposed change · ${escapeHtml(message.proposal.title)}</strong><p>${escapeHtml(message.proposal.description)}<br>Affected: ${escapeHtml(message.proposal.affected)}</p><div class="proposal-actions">${message.proposal.status==="pending"?`${button("Preview", "preview-proposal", "secondary", `data-index="${i}"`)}${button("Accept", "accept-proposal", "primary", `data-index="${i}"`)}${button("Reject", "reject-proposal", "ghost", `data-index="${i}"`)}`:badge(message.proposal.status,message.proposal.status==="Accepted"?"green":"")}</div></div>`:""}<time>${escapeHtml(message.time||"now")}</time></div></article>`).join("")}</div><div class="suggestion-list">${["Explain the selected asset", "Generate a SQL quality check", "Diagnose the last failed run"].map((prompt,i)=>`<button class="suggestion-button" data-action="ask-suggestion" data-prompt="${prompt}">${i===0?"✳":"↳"} ${prompt}</button>`).join("")}</div></div><form class="chat-compose" data-form="chat"><textarea name="prompt" placeholder="Ask about selected engineering context…" aria-label="Ask Dexter" required></textarea><div class="chat-compose-footer"><span class="tiny">Context sent: ${contextText.length?contextText.length+" item(s)":"none"}</span><button class="send-button" aria-label="Send prompt">↑</button></div></form><div class="chat-footnote">⌑ Ask Dexter uses deterministic scripted responses in this demo.</div>`;
  else if(state.contextTab==="properties") body=`<div class="context-scroll"><span class="eyebrow">CURRENT SELECTION</span><h2 style="font-size:12px">${escapeHtml(state.selectedNode?getPipeline(state).nodes.find(n=>n.id===state.selectedNode)?.title||getAsset(state).fullName:getAsset(state).fullName)}</h2><p class="tiny">Properties follow the current selected asset, node or operation.</p><div class="settings-row"><div><strong>Workspace</strong><small>${escapeHtml(getWorkspace(state).name)}</small></div></div><div class="settings-row"><div><strong>Default environment</strong><small>${escapeHtml(state.environment)}</small></div></div><div class="settings-row"><div><strong>Classification</strong><small>${escapeHtml(getAsset(state).classification)}</small></div>${badge(getAsset(state).classification,getAsset(state).classification==="Restricted"?"red":"")}</div><div class="section-heading"><h2>Context actions</h2></div>${button("Attach to Ask Dexter", "attach-current-context", "secondary")}</div>`;
  else body=`<div class="context-scroll"><span class="eyebrow">RECENT ACTIVITY</span><div class="timeline" style="margin-top:10px">${state.operations.map(op=>`<div class="timeline-item ${op.state==="Completed"?"done":op.state==="Failed"?"failed":""}"><strong>${escapeHtml(op.target)}</strong><small>${escapeHtml(op.state)} · ${escapeHtml(op.started)}</small></div>`).join("")}</div><div class="section-heading"><h2>Selected operation</h2></div>${button("Open Operations Center", "open-operations", "ghost")}</div>`;
  return `<div class="context-head"><h2>Context panel</h2><button class="icon-button" data-action="toggle-context" aria-label="Collapse contextual panel">›</button></div><div class="context-tabs">${[["assistant","✳ Ask Dexter"],["properties","Properties"],["activity","Activity"]].map(([id,label])=>`<button class="context-tab ${state.contextTab===id?"active":""}" data-action="context-tab" data-value="${id}">${label}</button>`).join("")}</div><div class="context-body">${body}</div>`;
}

export function renderStatusbar(state) {
  const active=state.operations.filter(o=>!['Completed','Failed','Cancelled'].includes(o.state)).length;
  return `<span class="status-dot"></span><span>Dexter local demo</span><span class="toolbar-divider"></span><span>${escapeHtml(getWorkspace(state).name)}</span><span class="status-spacer"></span><span class="mono">${escapeHtml(state.environment)} · ${state.sql.route==="DATABRICKS"?"Databricks SQL Mock":"DuckDB Local"}</span><span class="toolbar-divider"></span><span>${active?`${active} active operations`:"No active operations"}</span><span class="toolbar-divider"></span><span>UTF-8</span>`;
}

export function renderModalContent(state) {
  const modal=state.modal;
  if(!modal) return "";
  if(modal.type==="new-workspace") return `<form class="form-stack" data-form="new-workspace"><div class="field"><label>Workspace name</label><input name="name" placeholder="e.g. Customer 360" required></div><div class="field"><label>Business domain</label><select name="domain"><option>Customer</option><option>Sales</option><option>Finance</option><option>Risk</option><option>Operations</option></select></div><div class="field"><label>Description</label><textarea name="description" placeholder="What are you building?"></textarea></div><div class="field"><label>Repository</label><select name="repository"><option value="">Connect later</option>${state.repositories.filter(r=>r.access!=="Restricted").map(r=>`<option>${escapeHtml(r.path)}</option>`).join("")}</select></div><div class="toolbar" style="justify-content:flex-end">${button("Cancel","close-modal","secondary")}<button class="button primary">Create workspace</button></div></form>`;
  if(modal.type==="attach-asset") return `<form class="form-stack" data-form="attach-asset"><p class="tiny">Select existing assets to link to ${escapeHtml(getWorkspace(state).name)}. Assets remain in their original environments.</p><div class="pill-row">${state.assets.map(asset=>`<label class="pill-select"><input type="checkbox" name="assetIds" value="${escapeHtml(asset.id)}" ${getWorkspace(state).assets.includes(asset.id)?"checked":""}>${escapeHtml(asset.fullName)} · ${escapeHtml(asset.environment)}</label>`).join("")}</div><div class="toolbar" style="justify-content:flex-end">${button("Cancel","close-modal","secondary")}<button class="button primary">Save linked assets</button></div></form>`;
  if(modal.type==="clear-chat") return `<div class="notice info"><span>ⓘ</span><div><strong>Clear Ask Dexter conversation?</strong>This removes the visible demo thread from this browser. Your workspaces, assets and local demo data stay intact.</div></div><div class="toolbar" style="justify-content:flex-end;margin-top:13px">${button("Cancel","close-modal")}${button("Clear conversation","confirm-clear-chat","danger")}</div>`;
  if(modal.type==="reset-demo") return `<div class="notice error"><span>!</span><div><strong>Reset all local demo state?</strong>Workspace edits, chat history, created datasets, simulated operations and Pull Requests will return to the seed state.</div></div><div class="toolbar" style="justify-content:flex-end;margin-top:13px">${button("Cancel","close-modal")}${button("Reset demo","reset-demo","danger")}</div>`;
  if(modal.type==="new-product") return `<form class="form-stack" data-form="new-product"><div class="field"><label>Product name</label><input name="name" placeholder="Customer 360" required></div><div class="field"><label>Business domain</label><select name="domain"><option>Customer</option><option>Sales</option><option>Finance</option><option>Risk</option><option>Operations</option></select></div><div class="field"><label>Business purpose</label><textarea name="purpose" required placeholder="Describe the intended consumers and outcome"></textarea></div><div class="toolbar" style="justify-content:flex-end">${button("Cancel","close-modal")}<button class="button primary">Create product</button></div></form>`;
  if(modal.type==="operation") {const op=state.operations.find(item=>item.id===modal.id);return op?`<div class="toolbar">${badge(op.state,op.state==="Failed"?"red":op.state==="Completed"?"green":"amber")}${badge(op.type,"blue")}</div><h3 style="font-size:12px">${escapeHtml(op.target)}</h3><p class="tiny">${escapeHtml(op.phase||"Operation detail")} · ${escapeHtml(op.started)}</p>${op.progress<100?`<div class="progress-track"><span style="width:${op.progress}%"></span></div><div class="progress-label"><span>${op.progress}% complete</span><span>${escapeHtml(op.rows||op.bytes||"")}</span></div>`:""}${op.error?`<div class="notice error" style="margin-top:10px">${escapeHtml(op.error)}</div>`:""}<pre class="mono-block" style="margin-top:10px">${(op.logs||[]).map(escapeHtml).join("\n")}</pre><div class="toolbar" style="justify-content:flex-end;margin-top:10px">${op.state==="Failed"?button("Retry operation","retry-operation","primary",`data-id="${op.id}"`):button("Cancel operation","cancel-operation","danger",`data-id="${op.id}"`)}${button("Close","close-modal")}</div>`:"<p>Operation not found.</p>";}
  if(modal.type==="notifications") return `<div class="compact-list">${state.notifications.map((n,i)=>`<div class="compact-row"><span class="row-icon amber">${n.unread?"●":"○"}</span><div class="row-main"><strong>${escapeHtml(n.title)}</strong><small>${escapeHtml(n.detail)} · ${escapeHtml(n.time)}</small></div>${button("Open","notification-open","ghost",`data-index="${i}"`)}</div>`).join("")}</div><div class="toolbar" style="justify-content:flex-end;margin-top:10px">${button("Mark all read","mark-notifications-read")}${button("Done","close-modal")}</div>`;
  if(modal.type==="command") return `<div class="palette-modal"><input class="palette-search" id="command-search" placeholder="Type a screen or command…" autocomplete="off"><div class="palette-results" id="command-results">${screens.map((item,i)=>`<button class="palette-result" data-screen="${item.id}"><span class="row-icon">${i+1<10?`0${i+1}`:i+1}</span><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.module)}</small></span><kbd>↵</kbd></button>`).join("")}</div></div>`;
  if(modal.type==="delete-local") { const asset=state.assets.find(item=>item.id===state.localDeleteTarget); return `<div class="notice error"><span>!</span><div><strong>Delete this local snapshot?</strong>${asset?escapeHtml(asset.fullName):"Selected dataset"} will be removed from local views. Its remote source is unchanged.</div></div><div class="toolbar" style="justify-content:flex-end;margin-top:13px">${button("Keep snapshot","close-modal")}${button("Delete local copy","confirm-delete-local","danger")}</div>`; }
  if(modal.type==="confirm-action") return `<p class="tiny">${escapeHtml(modal.message||"Continue with this simulated action?")}</p><div class="toolbar" style="justify-content:flex-end;margin-top:13px">${button("Cancel","close-modal")}${button("Continue","confirm-generic","primary")}</div>`;
  return `<div class="empty-state"><strong>${escapeHtml(modal.title||"Dexter")}</strong><p>This experience is simulated. No external system is connected.</p>${button("Close","close-modal")}</div>`;
}
